// The learner goal and sub-goals of the A2 lessons written in code (a2/module01…20.js), by the lesson quality contract
// (docs/LESSON_QUALITY_CONTRACT.md A1–A3); merged into the course sheets by registry.js.
export const A2_LESSON_GOALS = {
  "a2-001": {"canDo": "Ma loen lühikest kirja inimese kohta ja kirjutan keelekoolile 40–60-sõnalise kirja endast: nimi, vanus, päritolu, elukoht, keeled ja töö.", "goals": {"g_vocab": "Õpilane kasutab sõnu nimi, aastat vana, pärit, keel, emakeel, kursus, küsimus, vastus, tutvuma ja tunneb lennujaama silte.", "g_read": "Õpilane leiab Sofia sõnumist emale, kuulamisest „Lennujaamas”, kolme õppija tutvustusest ja keelekooli kutsest nime, vanuse, elukoha, keeled ja töö.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lennujaamas” ja „Kolm õppijat” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab olema vorme (olen, oled, on; ei ole), küsisõnu ja mudelit pärit …-st, elan …-s.", "g_use": "Õpilane jutustab Sofia loo, küsitleb paarilist, räägib vestluses õpetajaga endast ja kirjutab keelekoolile 40–60-sõnalise vastuse."}, "tags": {"001_d_airport": "g_listen", "001_p_listen": "g_listen"}},
  "a2-002": {"canDo": "Ma saan kuuldust aru, kas inimesed ütlevad sina või teie, ja kirjutan uuele naabrile viisaka 50–70-sõnalise kirja teie-vormis.", "goals": {"g_vocab": "Õpilane kasutab väljendeid tere õhtust, meeldiv tutvuda, vabandust, palun korrake, aitäh, nägemiseni ja sõnu naaber, külaline, võõras.", "g_read": "Õpilane saab aru kuulamisest „Köögis”, Sofia kirjast „Trepil”, kohviku vestlusest, Malle telefonisõnumist ja Malle kirjast.", "g_listen": "Õpilane saab aru kuulamistekstidest „Köögis”, „Jaani kohvikus” ja „Malle sõnum” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane valib sina või teie, põhjendab valikut sõnaga sest ja kasutab teie-vorme (olete, räägite; korrake, rääkige, istuge).", "g_use": "Õpilane tervitab eri inimesi, kirjeldab pilti, helistab Mallele tagasi, salvestab häälsõnumi ja kirjutab Mallele 50–70-sõnalise kirja teie-vormis."}, "tags": {"002_d_family": "g_listen", "002_p_listen": "g_listen", "002_t_voice": "g_listen"}},
  "a2-003": {"canDo": "Ma räägin endast ja teistest olevikus jaatavas ja eitavas lauses (ma töötan, ma ei tööta) ja lepin teisega kokku, mida plakatile kirjutada.", "goals": {"g_vocab": "Õpilane kasutab sõnu töö, tööd otsima, pensionär, üliõpilane, õppima, korrus, praegu, natuke, hästi, kiiresti ja ametinimetusi.", "g_read": "Õpilane leiab Malle jutust naabritest, Sofia päevikust, Grete videost, maja teadetetahvlilt ja Oskari plakatilt, kes kus elab, töötab ja õpib.", "g_notice": "Õpilane pöörab tegusõnu olevikus (elan, elad, elab; räägin, õpin) ja teeb eituse ei + tüvi (ma ei tööta).", "g_use": "Õpilane räägib oma majast, küsib naabrilt infot, lepib Oskariga plakati sisu kokku, kirjutab plakatile 8–10 lauset ja salvestab video endast."}},
  "a2-004": {"canDo": "Ma räägin ametnikuga oma andmetest (nimi tähthaaval, sünniaeg, aadress, telefon), palun vea parandada ja täidan ankeedi.", "goals": {"g_vocab": "Õpilane kasutab ankeedi sõnu eesnimi, perekonnanimi, sünniaeg, aadress, postiindeks, e-post, kodakondsus, allkiri ja trükitähtedega.", "g_read": "Õpilane leiab isikukaartidest, linnaosa teatest, ametniku kõnest, perearstikeskuse kirjast ja Mareti sõnadest andmed ja vajaliku info.", "g_listen": "Õpilane saab aru kuulamistekstidest „Ametnik helistab” ja „Maret alustab tundi” (lüngad ja etteütlus).", "g_notice": "Õpilane loeb kuupäevi ja aadresse, ütleb e-posti ja nime tähthaaval ning kasutab vorme 14. märtsil, märtsis.", "g_use": "Õpilane helistab linnaosa valitsusse, tutvustab ennast kolm korda, täidab keelekooli ankeedi ja palub sekretäril andmete vea parandada."}, "tags": {"004_p_call": "g_listen", "004_t_listen": "g_listen", "004_p_dict": "g_listen"}},
  "a2-005": {"canDo": "Ma näitan kontrollis, et oskan rääkida ja kirjutada endast, täita ankeeti ning kasutada olema ja olevikuvorme (vähemalt 70%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 1 sõnu ja väljendeid (tutvumine, viisakus, ankeet) ilma abita.", "g_read": "Õpilane leiab kuulutusest ja sõnumist vajaliku info ning kuulab välja nime, numbri ja kuupäeva.", "g_listen": "Õpilane saab aru kuulamistekstidest „Tutvustus”, „Ankeet telefonis” ja „Õpetaja Maret” (lüngad).", "g_notice": "Õpilane kasutab olema ja olevikuvorme, eitust ja kohavorme (Tartust, Pärnus) vähemalt 70% õigesti.", "g_use": "Õpilane täidab ankeedi, kirjutab 40–60-sõnalise sõnumi ja peab tutvumisdialoogi."}, "tags": {"005_p_listen": "g_listen", "005_p_listen2": "g_listen", "005_t_listen": "g_listen"}},
  "a2-006": {"canDo": "Ma räägin oma perest ja lähedastest (vähemalt neli inimest, igaühe kohta üks detail) ja lepin pereliikmega kokku, mida pere pühapäeval teeb.", "goals": {"g_vocab": "Õpilane kasutab pere sõnu pere, vanemad, laps, poeg, tütar, vend, õde, abikaasa, vanaema, tädi ristsõnas ja sugulussõnade ühendamisel.", "g_read": "Õpilane leiab Oskari kooliteksti, kuulamise „Pühapäev Jaani juures”, kolme häälsõnumi, Viktori sõnumi ja ema kirja põhjal, kes kellega sugulane on.", "g_listen": "Õpilane saab aru kuulamistekstidest „Pühapäev Jaani juures” ja „Kolm häälsõnumit” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab mudelit mul on kaks venda, mul ei ole õde, kas sul on lapsi ning mitmust vennad, õed, lapsed.", "g_use": "Õpilane räägib oma perest ja sugupuust, lepib pereliikmega kokku pere pühapäeva ja vastab emale 40–50 sõnaga."}, "tags": {"006_d_meet": "g_listen", "006_p_messages": "g_listen"}},
  "a2-007": {"canDo": "Ma küsin „Kelle … see on?”, vastan omastavaga (See on Markuse kott. See on minu oma.) ja helistan keelekooli, et oma kadunud asja leida.", "goals": {"g_vocab": "Õpilane kasutab sõnu kelle, oma, asi, võti, kott, prillid, sall, müts, kaotama, leitud ka trepikoja teadetes ja tõlkes.", "g_read": "Õpilane leiab kooli teatest, pere vestlusest, keelekooli automaatteatest ja Tomi kõnest, kelle asi see on, kus see on ja millal selle saab.", "g_listen": "Õpilane saab aru kuulamistekstidest „Teade koolist”, „Keelekooli automaatvastaja” ja „Tom helistab” (lüngad).", "g_notice": "Õpilane moodustab omastava (Oskari, venna, õe, lapse, tütre; minu, sinu, nende), parandab kelle-vormi vead ja küsib Kelle … see on?", "g_use": "Õpilane helistab keelekooli ja leiab oma kadunud asja, täidab leitud asja kaardi ja kirjutab sõbrale 40–50-sõnalise sõnumi."}, "tags": {"007_d_school": "g_listen", "007_p_hours": "g_listen", "007_t_call": "g_listen"}},
  "a2-008": {"canDo": "Ma kirjutan 40–60-sõnalise kirjelduse inimese välimusest ja iseloomust (Ta on pikk ja rahulik. Tal on lühikesed tumedad juuksed.) ja võrdlen kahte inimest.", "goals": {"g_vocab": "Õpilane kasutab välimuse ja iseloomu sõnu pikk, lühike, hele, tume, juuksed, silmad, rahulik, sõbralik, aktiivne, tõsine.", "g_read": "Õpilane leiab Viktori ja Sofia jutust, lühikestest tekstidest, Malle jutust, Sofia kirjast ja Kadri häälsõnumist inimese välimuse ning tunneb ta ära.", "g_listen": "Õpilane saab aru kuulamistekstidest „Sofia ja Viktor vaatavad fotot”, „Kes see on?” ja „Kadri häälsõnum” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane eristab Ta on pikk ja Tal on pikad juuksed, ühildab omadussõna mitmuses ja võrdleb (pikem kui).", "g_use": "Õpilane kirjeldab pildil inimest, jätab sõbrale häälsõnumi ja kirjutab lähedasest inimesest 40–60-sõnalise teksti."}, "tags": {"008_d_photo": "g_listen", "008_p_clips": "g_listen", "008_t_call": "g_listen"}},
  "a2-009": {"canDo": "Ma kirjutan sõbrale 60–80-sõnalise kirja oma pere ja uute tuttavate kohta: kes nad on, kui vanad, kus elavad, mida teevad ja millised nad on.", "goals": {"g_vocab": "Õpilane kasutab sõnu vanus, amet, huvi, abielus, pensionär, naaber, rõõmus ja loeb visiitkaardilt ameti ning töökoha.", "g_read": "Õpilane leiab uute õpilaste tutvustustest, raadiost „Mustamäe inimesed”, Sofia blogist ja perefoto mustandist, kes, kui vana, kus elab, mida teeb.", "g_listen": "Õpilane saab aru kuulamistekstist „Raadio: Mustamäe inimesed” (küsimused kuuldu kohta ja etteütlus).", "g_notice": "Õpilane valib õige küsisõna (kes, kui vana, kust, kus, mida, milline, kas), paneb küsimuse kokku ja parandab küsimuse vead.", "g_use": "Õpilane salvestab jutu oma perefotost, valib paarilisega õhtuks foto ja kirjutab Katile 60–80-sõnalise kirja."}, "tags": {"009_d_radio": "g_listen", "009_p_dict": "g_listen"}},
  "a2-010": {"canDo": "Ma näitan kontrollis, et oskan rääkida perest, öelda, kelle oma asi on, ja kirjeldada inimest vähemalt kuue lausega (vähemalt 70%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 2 sõnu (pere ja sugulased, välimus, iseloom) ilma sõnapangata.", "g_read": "Õpilane lahendab Harno A2 lugemise ja kuulamise ülesanded pere ja inimeste teemal vähemalt 70% ulatuses.", "g_listen": "Õpilane saab aru kuulamistekstidest „Olga pere”, „Perefoto”, „Telefonikõne” ja „Anna kirjeldab” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti osastavat arvsõna järel, omastavat, omadussõna mitmust ja võrdlust (pikem kui).", "g_use": "Õpilane kirjeldab inimest vähemalt kuue lausega, kirjutab perefoto juurde 60–80 sõna ja peab dialoogi perest."}, "tags": {"010_d_listen": "g_listen", "010_p_listen": "g_listen", "010_p_listen2": "g_listen", "010_t_listen": "g_listen", "010_p_tf": "g_listen"}},
  "a2-011": {"canDo": "Ma kirjutan keelekooli lehte 40–60-sõnalise loo oma tavalisest päevast ja räägin sellest umbes minut, kasutades vähemalt kuut ajasõna.", "goals": {"g_vocab": "Õpilane kasutab sõnu hommikul, päeval, pärastlõunal, õhtul, öösel, ärkama, magama minema, tavaline ja päeva tervitusi.", "g_read": "Õpilane leiab kuulamisest „Hommik köögis”, Sofia kirjast, Grete kirjast emale ja Dmitri loost, mis kell keegi mida teeb, ning paneb loo lõigud järjekorda.", "g_notice": "Õpilane pöörab olevikus tegusõnu minema, tulema, sööma, jooma, tegema (lähen, tuleb, sööme, joob, teevad) ja paneb tegusõna lauses teisele kohale.", "g_use": "Õpilane intervjueerib paarilist, räägib oma päevast umbes minuti vähemalt kuue ajasõnaga ja kirjutab keelekooli lehte 40–60 sõna."}},
  "a2-012": {"canDo": "Ma helistan ja lepin telefonis kokku, mis kell ja kui kaua midagi toimub (pool kolm, kella üheksast viieni, enne / pärast), ning muudan vajadusel aega.", "goals": {"g_vocab": "Õpilane kasutab sõnu kell, pool, veerand, kolmveerand, algama, lõppema, kestma, alates, kuni, avatud ning loeb lahtiolekusilte.", "g_read": "Õpilane leiab lasteaia päevakavast, töökuulutustest, treeneri kirjast, juuksuri vestlusest ja telefonisõnumitest õige aja.", "g_listen": "Õpilane saab aru kuulamistekstidest „Kolm sõnumit” ja „Kadri sõnum” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane ütleb kella sõnadega (pool neli, veerand neli) ja moodustab kella üheksast kuni viieni, enne kella kuut, pärast tööd.", "g_use": "Õpilane helistab spordiklubisse ja hotelli, lepib uue aja kokku, salvestab Kadrile häälsõnumi ja kirjutab plaani kahele adressaadile."}, "tags": {"012_p_calls": "g_listen", "012_t_kadri": "g_listen"}},
  "a2-013": {"canDo": "Ma kirjutan pereõele 50–70-sõnalise kirja oma harjumustest ja ütlen õige sõnajärjega, kui tihti ma midagi teen (alati, tavaliselt, harva, mitte kunagi, kord nädalas).", "goals": {"g_vocab": "Õpilane kasutab sagedussõnu alati, tavaliselt, sageli, mõnikord, harva, mitte kunagi, iga päev, kord nädalas ja sõna harjumus.", "g_read": "Õpilane leiab kaartidelt, raadioküsitlusest, Malle kirjast, kooli liikumisnädala kirjast ja pereõe nõuannetest, kui tihti keegi midagi teeb.", "g_listen": "Õpilane saab aru kuulamistekstidest „Raadio küsib: kui tihti?” ja „Pereõe nõuanded” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane paneb sagedussõna õigesse kohta, teeb eituse ei … mitte kunagi ning ütleb kaks korda ja käin ujumas.", "g_use": "Õpilane täidab küsimustiku, räägib pereõega oma murest ja harjumustest, salvestab jutu uuest harjumusest ja kirjutab pereõele 50–70 sõna."}, "tags": {"013_d_survey": "g_listen", "013_t_heli": "g_listen"}},
  "a2-014": {"canDo": "Ma lepin korterikaaslastega kokku nädala plaani (kes, mis päeval, mis kell) ja kirjutan selle 70–90 sõnaga korteri vestlusesse.", "goals": {"g_vocab": "Õpilane kasutab sõnu nädal, nädalavahetus, kalender, vaba, kiire ja järjekorrasõnu kõigepealt, siis, pärast seda, lõpuks.", "g_read": "Õpilane leiab Sofia ja Grete sõnumitest, Jaani ja Malle häälsõnumist, mis päeval ja mis kell midagi toimub, ning mõtleb, mida see plaanile tähendab.", "g_listen": "Õpilane saab aru kuulamistekstidest „Jaani vastus” ja „Malle soovid” (lüngad, küsimused kuuldu kohta ja etteütlus).", "g_notice": "Õpilane moodustab vormid esmaspäeval, reedel, nädalavahetusel, esmaspäeviti, reedeti ning sel, järgmisel nädalal ja ühendab laused sõnadega ja, aga, sest.", "g_use": "Õpilane lepib korterikaaslastega nädala plaani kokku, kirjeldab pilti ja kirjutab korteri vestlusesse 70–90-sõnalise sõnumi."}, "tags": {"014_d_jaan": "g_listen", "014_t_malle": "g_listen", "014_p_dict": "g_listen"}},
  "a2-015": {"canDo": "Ma näitan kontrollis, et oskan rääkida oma päevast ja nädalast, öelda kellaaega ja sagedust ning kirjutada nädala plaani (vähemalt 70%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 3 sõnu (päev, kell, sagedus, nädal, päevakava) ilma sõnapangata.", "g_read": "Õpilane lahendab Harno A2 lugemise ja kuulamise ülesanded (kuulutus, teadaanne, telefonikõne) vähemalt 70% ulatuses.", "g_listen": "Õpilane saab aru kuulamistekstidest „Urmase nädal”, „Teade bussijaamas”, „Telefonikõne” ja „Uus tunniplaan” (lüngad, küsimused kuuldu kohta ja etteütlus).", "g_notice": "Õpilane kasutab õigesti kellaaega, alates–kuni, enne–pärast, sagedussõnu ja nädalapäevi.", "g_use": "Õpilane täidab päevakava, kirjutab 70–90-sõnalise nädala teksti, räägib oma päevast ja lepib aja kokku."}, "tags": {"015_d_listen": "g_listen", "015_p_listen": "g_listen", "015_p_listen2": "g_listen", "015_t_listen": "g_listen", "015_p_tf": "g_listen", "015_p_dict": "g_listen"}},
  "a2-016": {"canDo": "Ma kirjutan emale 60–80-sõnalise kirja oma kodust: mis toad seal on, mis mööbel kus on ja mis mulle kodus meeldib.", "goals": {"g_vocab": "Õpilane kasutab kodu sõnu tuba, köök, vannituba, esik, rõdu, mööbel, voodi, kapp, kirjutuslaud, tool ja nimetab mööbli igas toas.", "g_read": "Õpilane saab aru videokõnest Katiga, Sofia päevikust, Malle kirjast ja ema kirjast: toad, mööbel, kus mis on.", "g_listen": "Õpilane saab aru kuulamistekstist „Videokõne Katiga” (lüngad ja etteütlus).", "g_notice": "Õpilane ütleb, mis kus on: Köögis on laud; köögis, toas, kapis, esikus, aga rõdul, korrusel.", "g_use": "Õpilane kirjutab emale 60–80-sõnalise kirja oma kodust, kirjeldab pilti ja salvestab 30–60 sekundit oma toast."}, "tags": {"016_d_video": "g_listen", "016_p_dict": "g_listen"}},
  "a2-017": {"canDo": "Ma kirjutan korteri meelespea 7–9 lausega: kus asjad on, kuhu minna ja kust abi saada, kui kodus on probleem (kodus, koju, kodust; poes, poodi, poest).", "goals": {"g_vocab": "Õpilane kasutab sõnu kodu, pood, linn, vesi, lagi, põrand, pesumasin, naaber, katki ja lühivorme koju, poodi, tuppa, kinno.", "g_read": "Õpilane leiab maja vestlusest, kuulamisest „Hommik Malle juures”, Arvo teatest ja häälsõnumitest, kus keegi on, kuhu läheb ja mida teha.", "g_listen": "Õpilane saab aru kuulamistekstidest „Hommik Malle juures” ja „Kolm häälsõnumit” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane moodustab sisekohakäänded -s, -sse, -st (kodus, esikusse, poest) ja valib kus-, kuhu- või kust-vormi.", "g_use": "Õpilane kirjutab korteri meelespea 7–9 lausega, räägib telefonis majahaldurile probleemist ja salvestab 30–60 sekundit."}, "tags": {"017_d_listen": "g_listen", "017_t_messages": "g_listen"}},
  "a2-018": {"canDo": "Ma lepin pereliikmega saunaõhtu plaani kokku ja räägin, kus asjad on ja kuhu need panna (laual, lauale, laualt; tööl, tööle, töölt).", "goals": {"g_vocab": "Õpilane kasutab maaelu sõnu maal, talu, saun, järv, mets, aed, õues, laud, turg, rätik.", "g_read": "Õpilane saab aru Viktori kirjast, talu ringkäigust, rongide sõiduplaanist ja Kadri häälsõnumist: kus asjad on ja mida teha.", "g_listen": "Õpilane saab aru kuulamistekstidest „Teadaanded jaamas” ja „Kadri häälsõnum” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane moodustab väliskohakäänded -l, -le, -lt (laual, lauale, laualt), teab erandit õues ja valib sees- või peal-vormi.", "g_use": "Õpilane lepib telefonis saunaõhtu plaani kokku, valib koos partneriga kaasa võetavad asjad ja salvestab 30–60 sekundit."}, "tags": {"018_p_station": "g_listen", "018_t_kadri": "g_listen"}},
  "a2-019": {"canDo": "Ma helistan korterikuulutuse peale, küsin korteri ja naabruskonna kohta (poe kõrval, pargi lähedal) ja lepin kokku aja korterit vaatama.", "goals": {"g_vocab": "Õpilane kasutab sõnu naaber, linnaosa, asuma, kõrval, vastas, lähedal, taga, peatus, korter, vaikne ja kuulutuste sõnu.", "g_read": "Õpilane leiab jalutuskäigust Mallega, Mustamäe tekstist, maakleri jutust ja kuulutustest korteri asukoha, korruse ja hinna.", "g_listen": "Õpilane saab aru kuulamistekstist „Maakler räägib korterist” (lüngad ja etteütlus).", "g_notice": "Õpilane kasutab omastavat kaassõnaga (poe kõrval, pargi lähedal, kooli taga) ja tegusõna asuma (Maja asub …).", "g_use": "Õpilane helistab maaklerile kuulutuse peale, lepib kokku aja, salvestab oma korterivaliku ja kirjutab maaklerile 50–70 sõna."}, "tags": {"019_p_agent": "g_listen", "019_p_dict": "g_listen"}},
  "a2-020": {"canDo": "Ma näitan kontrollis, et oskan kirjeldada kodu ja naabruskonda ning kasutada vorme kus, kuhu ja kust (vähemalt 70%, kohavormid vähemalt 65%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 4 sõnu (kodu, mööbel, naabruskond) ilma abita.", "g_read": "Õpilane leiab kuulutusest ja teatest vajaliku info ning kuulab välja koha ja asja.", "g_listen": "Õpilane saab aru kuulamistekstidest „Kus asjad on?”, „Minu linnaosa” ja „Sõbra küsimused” (lüngad ja etteütlus).", "g_notice": "Õpilane kasutab sees- ja pealvorme ning kaassõnu kõrval, vastas, lähedal vähemalt 65% õigesti.", "g_use": "Õpilane teeb korteri plaani, kirjutab 60–80 sõna oma linnaosast ja peab korteri üürimise dialoogi."}, "tags": {"020_p_listen": "g_listen", "020_p_listen2": "g_listen", "020_t_listen": "g_listen", "020_d_dict": "g_listen"}},
  "a2-021": {"canDo": "Ma räägin, kuhu ma linnas lähen ja mida seal teen (apteeki, apteegis, apteegist), ja lepin sõbraga kokku vaba laupäeva plaani.", "goals": {"g_vocab": "Õpilane kasutab kohtade ja tegevuste sõnu apteek, pank, postkontor, raamatukogu, pakk, turg, keskus, kino, laenama, saatma ja ütleb, mida kus tehakse.", "g_read": "Õpilane leiab Sofia nimekirjast, Malle kõnest, linna kuulutustest, Jaani sõnumist ja laupäeva üritustest, kuhu minna, mis kell ja mida seal teha.", "g_listen": "Õpilane saab aru kuulamistekstist „Malle helistab” (lüngad ja etteütlus).", "g_notice": "Õpilane valib kohanimele kus-, kuhu- või kust-vormi (apteegis, apteeki, apteegist; raamatukokku, postkontorisse, turul) ja parandab oma esimese pakkumise.", "g_use": "Õpilane küsitleb kaaslasi, küsib raamatukogu infot, kirjutab oma linnast, lepib kokku vaba laupäeva plaani, salvestab jutu lemmikkohast ja kirjutab Jaanile teate."}, "tags": {"021_d_malle": "g_listen", "021_p_dict": "g_listen"}},
  "a2-022": {"canDo": "Ma saan aru teejuhisest, küsin teed ja kirjutan 50–70-sõnalise loo sellest, kuidas keegi linnas uue tee leiab.", "goals": {"g_vocab": "Õpilane kasutab tee sõnu tee, otse, paremale, vasakul, ristmik, sild, tramm, väljuma, kaugel, jalgsi.", "g_read": "Õpilane saab aru Sofia loost, Dmitri juhisest, tänaval küsimisest, Kadri sõnumist ja loo jätkust: kuhu minna, millega sõita ja kus pöörata.", "g_listen": "Õpilane saab aru kuulamistekstidest „Dmitri juhatab teed” ja „Vineeri peatuses” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane küsib viisakalt (Vabandage, kuidas ma saan …? Kas see on kaugel? Palun korrake!) ja kasutab kuni + -ni (ristmikuni) ning üle + omastav (üle silla).", "g_use": "Õpilane jutustab loo, juhatab ja kontrollib teed, ütleb oma arvamuse, kirjeldab pilti, salvestab oma tee ja kirjutab 50–70-sõnalise loo uuest teest."}, "tags": {"022_d_dmitri": "g_listen", "022_p_ask": "g_listen"}},
  "a2-023": {"canDo": "Ma annan juhiseid käskivas kõneviisis (mine, osta, ära oota; minge, ostke) ja selgitan suuliselt telefonis, kuidas bussijaamast keelekooli saab.", "goals": {"g_vocab": "Õpilane kasutab sõnu bussijaam, pilet, pangakaart, ekraan, valima, hoidma, ootama, unustama, takso, vanalinn.", "g_read": "Õpilane saab aru pere vestlusest, Jaani automaadijuhendist, trammipeatuse infost, giidi jutust, Lucía kirjast ja ema häälsõnumist: mida teha ja mis järjekorras.", "g_listen": "Õpilane saab aru kuulamistekstidest „Giid vanalinnas” ja „Ema häälsõnum” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane moodustab käsu sina- ja teie-vormis (oota, oodake; mine, minge; osta, ostke) ja keelu (ära oota, ärge oodake).", "g_use": "Õpilane proovib ema juhatada, kirjutab juhendi turistile, juhatab giidina, valib partneriga parima tee, juhatab ema telefonis, salvestab häälsõnumi ja vastab ema sõnumile."}, "tags": {"023_p_guide": "g_listen", "023_t_voice": "g_listen"}},
  "a2-024": {"canDo": "Ma saan kuuldust aru, mis kell kohad on avatud, ja kirjutan sõbrale 50–70-sõnalise kirja: kuidas kohvikusse saab ja millal see avatud on.", "goals": {"g_vocab": "Õpilane kasutab sõnu avatud, suletud, silt, sissepääs, väljapääs, lõuna, puhkepäev, korrus, kassa, tasuta.", "g_read": "Õpilane saab aru keskuse teadaannetest, automaatvastajast, siltidest, infolehest, Sofia ja Viktori plaanist ning Tomi häälsõnumist: mis kell, kus ja mis korrusel.", "g_listen": "Õpilane saab aru kuulamistekstidest „Keskuse teadaanded”, „Teeninduskeskuse automaatvastaja” ja „Sofia ja Viktor teevad plaani” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane ütleb aegu sõnadega (E–R 9–17 = esmaspäevast reedeni kella üheksast viieni) ja paneb teate sõnad õigesse järjekorda.", "g_use": "Õpilane täidab broneeringu, lahendab teeninduskeskuses probleemi, kutsub kaaslased kohvikusse, juhatab Tomi telefonis, salvestab jutu ja kirjutab Tomile kirja."}, "tags": {"024_d_clips": "g_listen", "024_d_phone": "g_listen", "024_p_plan": "g_listen"}},
  "a2-025": {"canDo": "Ma näitan kontrollis, et oskan nimetada kohti linnas, küsida ja juhatada teed, anda juhiseid käskivas kõneviisis ja lugeda silte ning lahtiolekuaegu (vähemalt 70%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 5 sõnu (kohad linnas, tee, sildid) ilma abita.", "g_read": "Õpilane saab aru siltidest, teatest ja teejuhisest ning kuulab välja suuna, koha ja aja.", "g_listen": "Õpilane saab aru kuulamistekstidest „Tee muuseumi”, „Tee jaama”, „Teadaanded” ja „Sõbra küsimused” (lüngad, küsimused kuuldu kohta ja etteütlus).", "g_notice": "Õpilane kasutab kohavorme ja käskivat kõneviisi (mine, minge, ära mine) vähemalt 70% õigesti.", "g_use": "Õpilane kirjutab 5–6-sammulise tee juhendi, salvestab häälsõnumi ja juhatab sõpra telefonis."}, "tags": {"025_d_listen": "g_listen", "025_p_listen": "g_listen", "025_p_listen2": "g_listen", "025_t_listen": "g_listen", "025_p_tf": "g_listen", "025_d_dict": "g_listen", "025_p_dict": "g_listen", "025_t_dict": "g_listen"}},
  "a2-026": {"canDo": "Ma räägin, mida ma söön ja joon ning mis mulle maitseb (söön leiba, mulle maitseb leib), küsin seda teistelt ja lepin kokku pere lõuna menüü.", "goals": {"g_vocab": "Õpilane kasutab toidu ja joogi sõnu leib, juust, piim, liha, kala, köögiviljad, puuviljad, magus, maitsema, turg raadioküsitluse valikutes ja toitude ühendamisel.", "g_read": "Õpilane leiab turuvestlusest, Sofia kirjast, Grete sõnumist ja Viktori häälsõnumist, kes mida sööb ja joob ning mida ei söö.", "g_listen": "Õpilane saab aru kuulamistekstidest „Laupäev Nõmme turul” ja „Viktori häälsõnum” (lüngad).", "g_notice": "Õpilane kasutab sööma / jooma + osastav (söön leiba, ei joo kohvi) ja meeldib / maitseb + nimetav (mulle maitseb leib) ning mitmuse osastavat (õunu).", "g_use": "Õpilane küsitleb teisi, räägib oma toidupäevast kolm korda, vastab küsimuskaardile, räägib telefonis Kadriga, lepib kokku lõuna menüü, kirjeldab pilti ja vastab Kadrile 40–50 sõnaga."}, "tags": {"026_d_market": "g_listen", "026_t_viktor": "g_listen"}},
  "a2-027": {"canDo": "Ma loen retsepti ja poe pakkumist, ütlen koguseid osastavaga (kaks liitrit vett, kilo kartuleid) ja lepin kokku, mida ja kui palju toidupäevaks ostame.", "goals": {"g_vocab": "Õpilane kasutab koguse sõnu kilo, liiter, pool, pakk, pudel, tükk, lusikas, natuke, tass, pott ning poe vestluse fraase.", "g_read": "Õpilane leiab retseptist, köögivestlusest, poe reklaamist, siltidelt ja pakenditelt, toidukaartidelt ja Mareti jutust kogused, hinnad ja vajaliku info.", "g_listen": "Õpilane saab aru kuulamistekstidest „Malle köögis” ja „Maret räägib toidupäevast” (lüngad ja etteütlus).", "g_notice": "Õpilane kasutab arv / mõõt + osastav (kolm porgandit, liiter piima, kilo kartuleid) ja parandab koguste vead.", "g_use": "Õpilane räägib oma lemmiktoidust, jutustab supitunnist, põhjendab, kus toitu osta, valib toidupäeva menüü 30 euro eest, kirjutab grupile 40–60 sõna ja salvestab oma maa toidu tutvustuse."}, "tags": {"027_d_kitchen": "g_listen", "027_t_maret": "g_listen", "027_p_dict": "g_listen"}},
  "a2-028": {"canDo": "Ma loen kohviku menüüd, tellin kohvikus endale ja sõbrale ning kirjutan kohviku kodulehele 70–90-sõnalise arvustuse.", "goals": {"g_vocab": "Õpilane kasutab kohviku sõnu menüü, tellima, soovima, magustoit, taimetoitlane, hommikusöök, tasuta, otsas, arve, kaardiga ja eristab kliendi ning teenindaja lauseid.", "g_read": "Õpilane loeb menüüd ja arvustust ning saab aru tellimise vestlustest ja kolmest telefonikõnest: toit, hind, aeg ja taimetoit.", "g_listen": "Õpilane saab aru kuulamistekstidest „Mida poisid tellivad?” ja „Kolm kõnet” (küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab tellimise mudeleid Ma soovin + osastav, Palun mulle üks …, Kas teil on …?, ilma …-ta ning paneb kohviku laused õigesse järjekorda.", "g_use": "Õpilane täidab külaliste küsitluse, küsitleb kolme inimest, kutsub Kati kohvikusse, seletab menüüd, lepib kokku tellimuse kahele ja kirjutab kodulehele 70–90-sõnalise arvustuse."}, "tags": {"028_d_listen": "g_listen", "028_p_calls": "g_listen"}},
  "a2-029": {"canDo": "Ma saan kuuldust aru tellimusest, hindadest ja muudatustest, kontrollin arvet ja kirjutan Kadrile 50–70-sõnalise kirja ostunimekirjaga.", "goals": {"g_vocab": "Õpilane kasutab sõnu hind, euro, sent, kokku, juurde, ilma, tellimus, viga, muutma, allergia ja ütleb hindu numbrite ja sõnadega.", "g_read": "Õpilane saab kahe kuulamise järel aru hindadest ja tellimuse muudatusest, leiab arvelt vea ning täidab Tomi ja Kadri kirja lüngad.", "g_notice": "Õpilane kasutab -ga ja ilma …-ta (kohv piimaga, tee ilma suhkruta), ütleb hinna sõnadega (kaks eurot kakskümmend senti) ja parandab tellimuse vead.", "g_use": "Õpilane lahendab arve vea, muudab tellimust häälsõnumis, tellib telefonis lõuna kuuele, kirjutab Kadrile 50–70-sõnalise kirja, parandab selle ja salvestab peo ostud."}},
  "a2-030": {"canDo": "Ma näitan kontrollis, et oskan nimetada toite, öelda koguseid osastavaga, tellida kohvikus ja aru saada hindadest (vähemalt 70%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 6 sõnu (toit, jook, kogus, kohvik, hind) ilma abita.", "g_read": "Õpilane leiab kuulutusest, teatest ja sõnumist vajaliku info ning kuuleb tellimuse ja hinna.", "g_listen": "Õpilane saab aru kuulamistekstidest „Tellimus kohvikus”, „Kohviku teade” ja „Õpetaja plaan” (lüngad).", "g_notice": "Õpilane kasutab osastavat (söön leiba, liiter piima), -ga / ilma …-ta ja hindu vähemalt 70% õigesti.", "g_use": "Õpilane täidab küsitluse, kirjutab 40–60-sõnalise sõnumi oma toidusoovidest ja tellib kohvikus ilma abita."}, "tags": {"030_p_listen": "g_listen", "030_p_listen2": "g_listen", "030_t_listen": "g_listen"}},
  "a2-031": {"canDo": "Ma ütlen poes, mida ma otsin (sinist tassi, sooja salli), küsin hinda ja värvi ning lepin sõbraga kokku, mis kingitus 40 euro eest osta.", "goals": {"g_vocab": "Õpilane kasutab poe sõnu tass, taldrik, lamp, kott, kingitus, sünnipäev, osakond, korrus, värv, otsima ning poe lausete algusi ja lõppe.", "g_read": "Õpilane leiab korteri vestlusest, Kaubahalli teadaandest, kolmest poe tekstist, Sofia kirjast ja kataloogi kaartidelt probleemi, korruse, hinna ja tingimuse.", "g_notice": "Õpilane kasutab otsima / vajama / mul on vaja + omadussõna ja nimisõna osastavas (sinist tassi, sooja salli, uusi saapaid) ja eristab nimetavat (mul on sinine tass).", "g_use": "Õpilane helistab poodi, räägib kolm korda, mida ta otsib, kirjutab kingituse plaani, avaldab arvamust, küsib poes teist võimalust, lepib sõbraga kingituse kokku, kirjutab 40–50 sõna ja salvestab pildi kirjelduse."}},
  "a2-032": {"canDo": "Ma ütlen hindu ja aegu õiges vormis (kahe euro eest, viie euroga, kaheksast kolmeni), küsin hinda ja lepin korterikaaslasega kokku, mida 25 euro eest osta.", "goals": {"g_vocab": "Õpilane kasutab sõnu hind, maksma, kokku, sularaha, rahakott, tükk, paar, purk, protsent, soodustus ja kuuleb kassas numbreid ning hindu.", "g_read": "Õpilane leiab turu vestlusest, turu teatest, Grete kirjast, Malle häälsõnumist ja kviitungilt hinna, aja ja vea.", "g_listen": "Õpilane saab aru kuulamistekstidest „Turul” ja „Malle häälsõnum” (lüngad).", "g_notice": "Õpilane kasutab arve käändes: kahe euro eest, viie euroga, kaheksast kolmeni, kümne protsendi soodustus, kuni viiekümne euroni, proovib vormi enne reeglit ja parandab vead.", "g_use": "Õpilane küsitleb hindade kohta, kutsub sõbra jõululaadale, lepib telefonis saabaste hinna kokku, kirjeldab pilti ja vastab küsimustele, lepib kokku toidukorvi 25 euro eest, kirjutab korterikaaslastele ja salvestab oma ostud."}, "tags": {"032_d_listen": "g_listen", "032_t_malle": "g_listen"}},
  "a2-033": {"canDo": "Ma saan kuuldust aru, mis on odavam, soojem või parem, palun poes teist suurust ja kirjutan sõbrale 50–70-sõnalise kirja, mida ma valisin ja miks.", "goals": {"g_vocab": "Õpilane kasutab sõnu proovima, sobima, kitsas, lai, pikk, lühike, kerge, paks, kasutatud, parem ja palub poes teist suurust või värvi.", "g_read": "Õpilane saab aru proovikabiini vestlusest, Helgi häälsõnumist ja raadiosaatest ning leiab Sofia kirjast ja Kristo tahvlilt hinna, suuruse ja erinevuse.", "g_listen": "Õpilane saab aru kuulamistekstidest „Proovikabiini juures”, „Ema vastab” ja „Raadiosaade” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane moodustab keskvõrde (odavam, soojem, parem … kui), küsib Kas teil on suuremat? ja paneb võrdluslaused õigesse järjekorda.", "g_use": "Õpilane küsitleb teisi, kirjutab poe arvustuse, seletab sõbrale, lepib kokku jope valiku, planeerib ja kirjutab Katile 50–70-sõnalise kirja, parandab selle ja salvestab pildi kirjelduse."}, "tags": {"033_d_fit": "g_listen", "033_d_listen": "g_listen", "033_p_radio": "g_listen"}},
  "a2-034": {"canDo": "Ma loen poe reegleid ja kviitungit, tagastan katkise asja (kahe aasta garantii, kuni reedeni, kviitungiga) ja kirjutan loo lõpu 60–80 sõnaga.", "goals": {"g_vocab": "Õpilane kasutab sõnu kviitung, tagastama, vahetama, katki, garantii, jooksul, kuni, kehtima, veekeetja, karp.", "g_read": "Õpilane leiab loost, telefonikõnest, poe reeglitest, teadaannetest, infolehest ja e-kirjast tähtaja, tingimuse ja hinna.", "g_notice": "Õpilane kasutab kuni …-ni, … jooksul, kahe aasta garantii, kviitungiga / ilma kviitungita ja parandab nende vead.", "g_use": "Õpilane jutustab loo kaks korda, kirjutab peatumata, räägib garantiist, kirjutab visiitkaardi järgi teate, tagastab infoletis katkise asja, täidab tagastamise vormi, kirjutab loo lõpu 60–80 sõnaga ja salvestab pildi kirjelduse."}},
  "a2-035": {"canDo": "Ma näitan kontrollis, et oskan poes küsida ja valida, saan aru hindadest, kviitungist ja kuulutustest ning lahendan probleemi kaubaga (vähemalt 70%, numbrid 80%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 7 sõnu (kaubad, arvud, suurus, värv, allahindlus, tagastus) ilma abita.", "g_read": "Õpilane leiab kuulutustest, kviitungist ja kirjast hinna, tähtaja ja tingimuse ning kuuleb summa vähemalt 80% õigesti.", "g_listen": "Õpilane saab aru kuulamistekstidest „Kassas”, „Tagastus” ja „Klienditeenindus” (lüngad).", "g_notice": "Õpilane kasutab osastavat, keskvõrret, arve käändes, -ni ja -ga / ilma …-ta vähemalt 70% õigesti.", "g_use": "Õpilane täidab tagastuse vormi, kirjutab poele 40–60 sõna ja visiitkaardi järgi teksti, kirjeldab pilti ja lahendab poes ostuprobleemi."}, "tags": {"035_p_listen": "g_listen", "035_p_listen2": "g_listen", "035_t_listen": "g_listen"}},
  "a2-036": {"canDo": "Ma loen panga infot, broneerin telefonis aja, muudan seda ja kirjutan pangale 50–70-sõnalise e-kirja uue aja kohta.", "goals": {"g_vocab": "Õpilane kasutab broneerimise sõnu ja fraase: aeg, vaba, kinni, sobima, varem, hiljem, muutma, kinnitama, tühistama, kalender.", "g_read": "Õpilane leiab panga e-kirjast, hinnakirjast ja häälsõnumist päeva, kellaaja, hinna ja selle, mida kaasa võtta.", "g_listen": "Õpilane saab aru kuulamistekstidest „Sofia helistab panka” ja „Kristi häälsõnum” (lüngad).", "g_notice": "Õpilane kasutab mudeleid Soovin aega…, Kas teil on … vaba aega?, Kas … sobib?, Kas on võimalik tulla varem / hiljem? ja ütleb päeva millal-vormis (kolmapäeval, järgmisel nädalal).", "g_use": "Õpilane broneerib ja muudab aega telefonis, kirjutab visiitkaardi järgi teksti ja pangale 50–70-sõnalise e-kirja uue aja kohta."}, "tags": {"036_d_call": "g_listen", "036_t_voice": "g_listen"}},
  "a2-037": {"canDo": "Ma saan kuuldust aru asutuse reeglitest (pean, võin, ei tohi, siin makstakse) ja kirjutan kooli lehte 40–60-sõnalise kirjelduse puhkeruumi reeglitest.", "goals": {"g_vocab": "Õpilane kasutab reeglite sõnu: reegel, järjekord, ootama, dokument, lubatud, keelatud, kviitung ja saab aru siltidest.", "g_read": "Õpilane saab aru valvuri ja teenindaja selgitustest ning Ene kirjast: mida peab, mida võib ja mida ei tohi teha.", "g_listen": "Õpilane saab aru kuulamistekstidest „Valvur selgitab” ja „Infoletis” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane valib modaalverbi ja õige infinitiivi (pean ootama, võin oodata, ei tohi süüa) ja tunneb ära umbisikulise vormi (avatakse, makstakse, ei suitsetata).", "g_use": "Õpilane lepib kokku puhkeruumi reeglid, kirjutab neist 40–60-sõnalise teksti ja räägib oma maja või töökoha reeglitest."}, "tags": {"037_d_guard": "g_listen", "037_p_desk": "g_listen"}},
  "a2-038": {"canDo": "Ma saan kuuldust aru vormi täitmise juhistest (täitke, kirjutage, märkige) ja räägin registraatoriga oma andmetest, kui vormis on viga.", "goals": {"g_vocab": "Õpilane kasutab vormi sõnu: vorm, avaldus, lahter, allkiri, kuupäev, andmed, aadress, trükitähed, kohustuslik, perearst.", "g_read": "Õpilane saab aru raamatukoguhoidja ja registraatori juhistest ning perearstikeskuse juhendist: mis on kohustuslik ja kuhu avaldus viia.", "g_listen": "Õpilane saab aru kuulamistekstidest „Infoletis” ja „Registraator Merike selgitab” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane moodustab teie-käsu (täitke, kirjutage, valige, märkige, andke, tooge) ja keelu (ärge unustage).", "g_use": "Õpilane räägib registraatoriga oma andmetest, parandab avalduse, aitab sõbral arsti valida ja täidab küsimustiku."}, "tags": {"038_d_listen": "g_listen", "038_p_steps": "g_listen"}},
  "a2-039": {"canDo": "Ma loen telefonipoe ja klienditeeninduse infot ning helistan klienditeenindusse, et oma probleem lahendada.", "goals": {"g_vocab": "Õpilane kasutab telefoni sõnu: helistama, kõne, klienditeenindus, teenindaja, kordama, tähthaaval, leping, tagasi helistama.", "g_read": "Õpilane leiab klienditeeninduse infost, SIM-kaardi juhendist, automaadi teadetest ja häälsõnumitest numbri, aja ja järgmise sammu.", "g_listen": "Õpilane saab aru kuulamistekstidest „Kolm häälsõnumit” ja „Oti häälsõnum” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab telefoniväljendeid Mis küsimuses te helistate?, Palun oodake, Ma ühendan teid…, Palun korrake ja ütleb nime tähthaaval.", "g_use": "Õpilane helistab klienditeenindusse, ütleb põhjuse, palub korrata, lepib kokku järgmise sammu ja vastab e-kirjale."}, "tags": {"039_p_voice": "g_listen", "039_t_ott": "g_listen"}},
  "a2-040": {"canDo": "Ma näitan kontrollis, et oskan broneerida aega, kasutada pean / saan / võin / tohin, täita vormi ja saada aru teeninduskõnest (vähemalt 70%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 8 sõnu (aeg, vorm, taotlus, allkiri, järjekord, klienditeenindus) ilma sõnapangata.", "g_read": "Õpilane lahendab Harno A2 vormis lugemise (teade, e-kiri lünkadega) ja kuulamise (häälsõnum, teeninduskõne) vähemalt 70% ulatuses.", "g_listen": "Õpilane saab aru kuulamistekstidest „Häälsõnum”, „Kõne pangas” ja „Perearstikeskuse vastus” (lüngad, küsimused kuuldu kohta ja etteütlus).", "g_notice": "Õpilane kasutab õigesti modaalverbe ja infinitiivi, teie-käsku, päeva millal-vormi ja telefoniväljendeid.", "g_use": "Õpilane täidab vormi, kirjutab 40–60-sõnalise e-kirja aja saamiseks ja lahendab teenindusasja telefonis."}, "tags": {"040_p_listen": "g_listen", "040_p_listen2": "g_listen", "040_t_listen": "g_listen", "040_p_tf": "g_listen", "040_d_dict": "g_listen"}},
  "a2-041": {"canDo": "Ma loen lugu, ütlen, mis mul valutab ja kuidas ma end tunnen (mul valutab pea, mul on palavik), ning kirjutan loo järje 60–80 sõnaga.", "goals": {"g_vocab": "Õpilane kasutab sõnu pea, kurk, kõht, selg, jalg, palavik, köha, nohu, haige, valutama ja ühendab probleemi nõuandega.", "g_read": "Õpilane leiab loost, köögivestlusest, Helgi kirjast ja Anna sõnumist, mis kellel valutab, ja kuuleb kraadid ja kellaajad õigesti.", "g_notice": "Õpilane kasutab mudeleid mul valutab pea / mul valutavad jalad, mul on palavik, ma olen haige ja kehaosade mitmust.", "g_use": "Õpilane jutustab loo, küsib ja ütleb pargipingil, mis viga on, vastab sõnumile, salvestab pildi kirjelduse ja kirjutab loo järje 60–80 sõnaga."}},
  "a2-042": {"canDo": "Ma saan kuuldust aru, mis kellelgi viga on ja mida tal on vaja (tal valutab kõrv, mul ei ole palavikku), ning kirjutan sõbrale 50–70-sõnalise kirja oma enesetundest.", "goals": {"g_vocab": "Õpilane kasutab sõnu terve, hammas, kõrv, silm, tervis, vaja, nädal, rohi, leiab perearstikeskuse lehe lõikudele pealkirja ja täidab patsiendi kaarte.", "g_read": "Õpilane saab aru kõnest perearstikeskusesse, korteri vestlusest, raadiosaatest, Helgi perejutust ja pereõe häälsõnumist: kellel mis on ja mida tal on vaja.", "g_listen": "Õpilane saab aru kuulamistekstidest „Sofia helistab”, „Raadio: talv ja gripp” ja „Ema räägib” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab kellel-vormi (mul, sul, tal, Sofial, lapsel), eitust osastavaga (mul ei ole palavikku) ja eristab ma olen väsinud ↔ mul on külm.", "g_use": "Õpilane küsib kolmelt inimeselt, seletab pere olukorda, lepib korterikaaslasega abi kokku, salvestab pildi kirjelduse ja kirjutab sõbrale 50–70-sõnalise kirja."}, "tags": {"042_d_call": "g_listen", "042_d_radio": "g_listen", "042_p_family": "g_listen"}},
  "a2-043": {"canDo": "Ma räägin arstiga: ütlen, mis mul viga on, vastan küsimustele Millal see algas? ja Kui kaua? ning kordan arsti soovitused (võtke, puhake, ärge tõstke).", "goals": {"g_vocab": "Õpilane kasutab sõnu arst, algama, tõstma, puhkama, soovitama, retsept, keha, lihas, valu, kestma ja kuuleb teatest kabineti ja korruse.", "g_read": "Õpilane leiab vastuvõtu vestlusest, Anna sõnumist, perearsti nõuannetest ja kirjast, millal valu algas, mida tuleb teha ja mida ei tohi.", "g_notice": "Õpilane moodustab teie-käsu (võtke, puhake, jooge, ärge tõstke), küsib Millal see algas? Kui kaua? ja parandab nende vead.", "g_use": "Õpilane räägib arstikäigust, helistab ülemusele, kirjeldab pilti eksamivormis, peab pereõega vastuvõtu vestluse ja kirjutab ülemusele, mida õde ütles."}},
  "a2-044": {"canDo": "Ma loen ravimi infot ja vastuvõtuaega (kaks tabletti, kolm korda päevas, pärast sööki) ja helistan perearstikeskusesse, et uus aeg kokku leppida.", "goals": {"g_vocab": "Õpilane kasutab sõnu võtma, tablett, kord, apteek, kabinet, vastuvõtt, põlv, ootama, karp ja seob infolehe lause tähendusega.", "g_read": "Õpilane leiab Viktori sõnumist, apteegi teadetest, pakenditelt ja ravimikavast annuse, sageduse, aja ja kabineti ning otsustab, kas tegevus on õige.", "g_notice": "Õpilane kasutab arvu järel osastavat (kaks tabletti, kolm korda, viis päeva) ja väljendeid enne sööki, pärast sööki, kabinetis.", "g_use": "Õpilane seletab Viktorile, täidab veebivormi ja kava, lepib kokku abi laadal, salvestab pildi kirjelduse ja helistab, et muuta vastuvõtuaega."}},
  "a2-045": {"canDo": "Ma näitan kontrollis Harno A2 vormis, et saan aru tervise tekstidest ja kuuldust, kirjutan lühikese sõnumi ja räägin arstiga (igas osas vähemalt 80%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 9 sõnu (keha, haigused, arst, ravim, visiit) ilma sõnapangata.", "g_read": "Õpilane lahendab Harno A2 vormis lugemise (R1–R5) ja kuulamise (L2, L3, L4) igas osas vähemalt 80% ulatuses.", "g_listen": "Õpilane saab aru kuulamistekstidest „Raadiosaade”, „Häälsõnum” ja „Sõbrad räägivad” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mul on / mul valutab, eitust ei ole palavikku, teie-käsku ja numbri järel osastavat.", "g_use": "Õpilane kirjutab visiitkaardi järgi teksti ja teksti oma tervisest, tutvustab ennast, kirjeldab pilti ja peab arstiga vestluse."}, "tags": {"045_t_l2": "g_listen", "045_t_l3": "g_listen", "045_t_l4": "g_listen"}},
  "a2-046": {"canDo":"Ma loen huviringide kava ja kuulutusi, räägin oma hobidest ja lepin sõbraga kokku, mis ringi me läheme.","goals":{"g_vocab":"Õpilane kasutab hobide sõnu: hobi, vaba aeg, trenn, ring, proovima, male, võrkpall, kudumine, laulma, tantsima.","g_read":"Õpilane loeb blogi, kuulutusi ja ringide kava ning leiab sealt aja, hinna ja koha.","g_listen":"Õpilane saab aru kuulamistekstist „Grete häälsõnum” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane moodustab käima + -mas (käin ujumas), mängima + osastav (mängin malet) ja hobi nime -mine (lugemine).","g_use":"Õpilane räägib oma hobidest, lepib sõbraga kokku ühe ringi ja põhjendab valikut."},"tags":{"046_p_grete":"g_listen","046_p_tf":"g_listen"}},
  "a2-047": {"canDo":"Ma saan kuuldust aru, mis inimestele meeldib, räägin oma eelistustest ja lepin perega kokku, mida me pühapäeval teeme.","goals":{"g_vocab":"Õpilane kasutab eelistuse sõnu: meeldima, väga, eriti, üldse, lemmik, igav, lõbus, huvitav, eelistama.","g_read":"Õpilane saab kuuldust ja loetust aru, mis kellelegi meeldib ja mis mitte.","g_listen":"Õpilane saab aru kuulamistekstidest „Jaan ja Viktor verandal” ja Raadio „Mustamäe hääl (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane moodustab laused mulle meeldib + nimetav (muusika) või da-vorm (tantsida), mulle meeldivad + mitmus, mulle ei meeldi.","g_use":"Õpilane küsib ja räägib, mis meeldib, võrdleb eelistusi ja lepib teistega kokku."},"tags":{"047_d_chat":"g_listen","047_p_radio":"g_listen"}},
  "a2-048": {"canDo":"Ma saan kuuldust aru kutsest, kirjutan sõbrale 50–70-sõnalise kirja ja kutsun ta kontserdile või vastan kutsele põhjusega.","goals":{"g_vocab":"Õpilane kasutab kutse sõnu ja väljendeid: kutse, kutsuma, kontsert, etendus, Hea meelega!, Kahjuks ei saa, Aitäh kutse eest, kohtume.","g_read":"Õpilane saab aru kuuldud ja loetud kutsest ning leiab aja, koha ja põhjuse.","g_listen":"Õpilane saab aru kuulamistekstidest „Kolm häälsõnumit” ja „Maret kutsub klassi teatrisse” (lüngad).","g_notice":"Õpilane kasutab kuhu-vormi (kinno, teatrisse, kontserdile) ja lauseid tahtma + da-vorm (Kas sa tahad tulla?), sest ja aga.","g_use":"Õpilane kutsub sõbra, vastab jah või ei põhjusega, pakub uue aja ja kirjutab selle kohta kirja."},"tags":{"048_d_voice":"g_listen","048_p_trip":"g_listen"}},
  "a2-049": {"canDo":"Ma loen ürituste kuulutusi ja kirjutan uue õpilase vaba aja juhti 60–80-sõnalise soovituse: aeg, koht, hind ja miks minna.","goals":{"g_vocab":"Õpilane kasutab ürituse sõnu: üritus, näitus, töötuba, pilet, tasuta, algus, kestus, sissepääs, registreerimine.","g_read":"Õpilane loeb kuulutust ja kuulab teateid ning leiab aja, koha, hinna ja kestuse.","g_listen":"Õpilane saab aru kuulamistekstidest „Kaheksa teadet”, „Kes läheb kuhu?” ja „Kultuurimaja kassas” (küsimused kuuldu kohta).","g_notice":"Õpilane kasutab aega ja hinda õiges vormis: kella kümnest kaheni, kaks tundi, viis eurot, laupäeval.","g_use":"Õpilane valib ürituse, räägib sellest teistele ja kirjutab soovituse uuele õpilasele."},"tags":{"049_d_clips":"g_listen","049_d_who":"g_listen","049_p_desk":"g_listen"}},
  "a2-050": {"canDo":"Ma näitan eksamis, et loen kuulutusi ja kirja, saan kuuldust aru, kirjutan kutse ja räägin oma vabast ajast (eesmärk on vähemalt 80% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli 10 sõnu ja väljendeid (hobid, meeldima, kutse, üritus, pilet) ilma abita.","g_read":"Õpilane lahendab lugemise ja kuulamise ülesanded Harno A2 vormis etteantud ajaga.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiosaade”, „Teade” ja „Vestlus” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab vorme käin ujumas, mängin malet, mulle meeldib tantsida, kinno, kella kümnest kaheni.","g_use":"Õpilane kirjutab teksti visiitkaardi järgi ja kutse, kirjeldab pilti ja küsib ning vastab ideekaardi järgi."},"tags":{"050_t_l1":"g_listen","050_t_l2":"g_listen","050_t_l3":"g_listen","050_t_l4":"g_listen","050_d_dict":"g_listen"}},
  "a2-051": {"canDo": "Ma saan kuuldust aru, mis ilm on (sajab vihma, puhub tuul, on kümme kraadi sooja), ja kirjutan sõbrale 50–70-sõnalise kirja ilmast ja aastaaegadest.", "goals": {"g_vocab": "Õpilane kasutab ilma ja aastaaegade sõnu: kevad, suvi, sügis, talv, päike, vihm, lumi, tuul, soe, külm, ning teeb nimisõnast omadussõna.", "g_read": "Õpilane saab raadiost, teadetest ja häälsõnumist aru, mis ilm on, ning valib kuulutuste seast ilmaga sobiva tegevuse.", "g_listen": "Õpilane saab aru kuulamistekstidest „Raadio: neli aastaaega”, „Keeletunnis” ja „Lühikesed teated” (lüngad, küsimused kuuldu kohta ja etteütlus).", "g_notice": "Õpilane ütleb sajab vihma / lund, puhub tuul, paistab päike, kümme kraadi sooja ja kasutab vorme kevadel, suvel, sügisel, talvel.", "g_use": "Õpilane räägib ilmast ja oma lemmik aastaajast, lepib ilma järgi plaani kokku ning kirjutab sõbrale kirja ilmast ja plaanist."}, "tags": {"051_d_radio": "g_listen", "051_d_class": "g_listen", "051_p_clips": "g_listen", "051_p_dict": "g_listen"}},
  "a2-052": {"canDo": "Ma võrdlen kahte kohta (soojem, odavam, parem kui), räägin, kumb on parem ja miks, ning lepin kokku, kuhu minna.", "goals": {"g_vocab": "Õpilane kasutab sõnu võrdlema, parem, halb, odav, kallis, talu, meri, hind, koht ja sorteerib kahe koha omadusi.", "g_read": "Õpilane saab kõnest ja tekstidest aru, millised on kaks kohta, ning leiab, mis sobib igale inimesele.", "g_notice": "Õpilane moodustab keskvõrde (soojem, parem, odavam), kasutab sõna kui ja sama vormi mõlemal pool (Pärnus … kui Kõrvemaal).", "g_use": "Õpilane küsib ja vastab ideekaardi järgi, lepib kokku, kuhu retk läheb, helistab Enele ja kirjutab Lucíale."}},
  "a2-053": {"canDo": "Ma loen lugu ja ilmateadet (hakkab sadama, temperatuur langeb, miinus kümme kraadi) ja kirjutan loo lõpu 60–80 sõnaga.", "goals": {"g_vocab": "Õpilane kasutab sõnu ilmateade, temperatuur, kraad, tõusma, langema, torm, libe, mets ja kirjutab üles temperatuurid.", "g_read": "Õpilane loeb Viktori lugu ja teksti ilmamehest ning saab raadio ilmateatest aru.", "g_listen": "Õpilane saab aru kuulamistekstist „Ilmateade raadios” (küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab minevikku sadas, puhus, paistis, langes, väljendeid hakkab sadama, pluss, miinus ja kraadi.", "g_use": "Õpilane jutustab loo, annab ilmateate, valib raadio jaoks tähtsama info ja kirjutab loole lõpu."}, "tags": {"053_d_forecast": "g_listen", "053_p_tf": "g_listen"}},
  "a2-054": {"canDo": "Ma loen sõbra küsimust ilma ja riiete kohta ning räägin telefonis, mida selga panna ja kaasa võtta (pane jope selga, võta vihmavari kaasa, ära unusta mütsi).", "goals": {"g_vocab": "Õpilane kasutab riiete sõnu: jope, müts, kindad, sall, saapad, kampsun, vihmavari ning sõnu panema, võtma, unustama.", "g_read": "Õpilane leiab sõprade sõnumitest, Ene kirjast ja Viktori teatest, mis riided sobivad ja mida on vaja.", "g_listen": "Õpilane saab aru kuulamistekstist „Kes mida paneb?” (küsimused kuuldu kohta ja etteütlus).", "g_notice": "Õpilane kasutab käskivat vormi pane, võta, ära unusta, pange, võtke, kohti selga, pähe, jalga, kätte, kaela ja põhjust sõnaga sest.", "g_use": "Õpilane annab telefonis nõu, kirjeldab pilti, lahendab probleemi poes, kirjutab sõnumi ja salvestab nõuanded."}, "tags": {"054_d_family": "g_listen", "054_p_dict": "g_listen"}},
  "a2-055": {"canDo": "Ma näitan kontrollis Harno A2 vormis, et saan aru ilmateatest ja tekstidest ilma kohta, kirjutan lühikese sõnumi, võrdlen ja annan nõu riiete kohta (igas osas vähemalt 80%).", "goals": {"g_vocab": "Õpilane kasutab mooduli 11 sõnu (ilm, aastaajad, ilmateade, riided) ilma sõnapangata.", "g_read": "Õpilane lahendab Harno A2 vormis lugemise (R1–R5) ja kuulamise (L1–L4) igas osas vähemalt 80% ulatuses.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiosaade”, „Ilmateade” ja „Sõbrad räägivad” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti ilmaväljendeid, keskvõrret ja sõna kui, käskivat vormi ja kohti selga, pähe, jalga, kätte.", "g_use": "Õpilane kirjutab visiitkaardi järgi teksti ja kutse, tutvustab ennast, kirjeldab pilti ja annab rollimängus nõu."}, "tags": {"055_t_l1": "g_listen", "055_t_l2": "g_listen", "055_t_l3": "g_listen", "055_t_l4": "g_listen"}},
  "a2-056": {"canDo":"Ma saan kuuldust aru, kuidas kuhugi saab, ja kirjutan sõbrale 50–70-sõnalise kirja: millega sõita, kust pilet osta ja kus maha tulla.","goals":{"g_vocab":"Õpilane kasutab transpordi ja pileti sõnu: buss, tramm, rong, laev, sadam, peatus, jalgsi, sõit, kohver, üks ots, edasi-tagasi.","g_read":"Õpilane saab kuuldust ja kirjast aru, kuidas kuhugi saab: transport, peatus, aeg ja hind.","g_listen":"Õpilane saab aru kuulamistekstidest „Kati helistab Sofiale”, „Raadio: bussijuht Toivo” ja „Kati häälsõnum” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane moodustab -ga vormi (bussiga, rongiga) ja eristab peatuses / peatusesse / peatusest; jalgsi ilma -ga.","g_use":"Õpilane kirjutab sõbrale 50–70-sõnalise kirja teekonnast ning selgitab teed telefonis."},"tags":{"056_d_call":"g_listen","056_p_radio":"g_listen","056_t_voice":"g_listen","056_p_dict":"g_listen"}},
  "a2-057": {"canDo":"Ma saan kuuldust aru jaama teadetest, leian sõiduplaanist aja ja platvormi ning lepin teisega kokku reisiplaani.","goals":{"g_vocab":"Õpilane kasutab sõiduplaani sõnu: väljub, saabub, hilineb, platvorm, ümberistumine, tühistatud, tabloo, sõiduplaan.","g_read":"Õpilane saab aru jaama teadetest ning leiab sõiduplaanist ja siltidelt aja, platvormi, hinna ja ümberistumise.","g_listen":"Õpilane saab aru kuulamistekstidest „Maret selgitab tööd” ja „Kaheksa teadet” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab vorme väljub Tallinnast, saabub Tartusse, teiselt platvormilt, hilineb kümme minutit.","g_use":"Õpilane lepib teisega kokku reisiplaani (koht, transport, aeg, hind) ja kirjutab selle lühidalt üles."},"tags":{"057_d_maret":"g_listen","057_p_clips":"g_listen"}},
  "a2-058": {"canDo":"Ma loen piletireegleid, ostan kassas pileti ja kirjutan bussifirmale 60–80-sõnalise vastuse: mis juhtus ja mida ma palun.","goals":{"g_vocab":"Õpilane kasutab kassa sõnu: täispilet, sooduspilet, kassa, järjekord, otse, automaat, vahetama.","g_read":"Õpilane loeb piletireegleid ja bussifirma kirja ning saab aru kassavestlusest ja igapäevastest viisakusväljenditest.","g_listen":"Õpilane saab aru kuulamistekstidest „Vestlus kassas” ja „Kes mida ostis?” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane moodustab küsimusi Mis kell…? Kust…? Kui palju…? Kas…? ja ütleb kaks piletit, kolm sooduspiletit.","g_use":"Õpilane ostab kassas pileti, lahendab probleemi (buss täis) ja vastab firma kirjale 60–80 sõnaga."},"tags":{"058_d_desk":"g_listen","058_p_order":"g_listen"}},
  "a2-059": {"canDo":"Ma loen reisijuttu ja räägin 6–8 lausega oma reisist minevikus: kuhu ja millega ma sõitsin, mida nägin ja millal tagasi tulin.","goals":{"g_vocab":"Õpilane kasutab reisi sõnu teekond, jõudma, lahkuma, tagasi, jalutama ning ajasõnu eile, eelmisel nädalal, aasta tagasi.","g_read":"Õpilane leiab reisijutust ja kuuldud tekstist, kuhu, millega, kui kaua ja millal inimene sõitis.","g_listen":"Õpilane saab aru kuulamistekstidest „Kati ajad” ja „Raadio: Tomi reis” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane moodustab lihtmineviku (käisin, läksin, tulin, olin, nägin, sõitsin), eituse (ei tulnud) ja küsib: Kuhu sa sõitsid?","g_use":"Õpilane räägib oma reisist 6–8 lausega, küsib teiselt tema reisi kohta ja kirjeldab pilti."},"tags":{"059_d_numbers":"g_listen","059_p_radio":"g_listen","059_p_dict":"g_listen"}},
  "a2-060": {"canDo":"Ma näitan proovieksamis, et loen silte ja kirja, saan kuuldust aru, kirjutan sõnumi ja räägin reisimisest (eesmärk on vähemalt 80% igas osas).","goals":{"g_vocab":"Õpilane kasutab mooduli 12 sõnu (transport, pilet, platvorm, väljub, hilineb, lennujaam, sadam, reisija) ilma sõnapangata.","g_read":"Õpilane lahendab lugemise ja kuulamise ülesanded Harno A2 vormis etteantud ajaga, eesmärk on vähemalt 80%.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiosaade”, „Teade” ja „Vestlus” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab -ga vormi, kus/kuhu/kust vorme, väljub/saabub/hilineb ja lihtminevikku õigesti.","g_use":"Õpilane kirjutab teksti visiitkaardi järgi ja sõnumi või kirjelduse ning räägib pildist ja küsib kaardi järgi."},"tags":{"060_t_l1":"g_listen","060_t_l2":"g_listen","060_t_l3":"g_listen","060_t_l4":"g_listen","060_d_dict":"g_listen"}},
  "a2-062": {"canDo":"Ma loen lugu töövestlusest ja kirjutan 60–80 sõnaga loo lõpu: mida inimene peab tegema, mida ta oskab ja mis juhtub (pean + ma-vorm, oskan + da-vorm).","goals":{"g_vocab":"Õpilane kasutab sõnu pidama, oskama, juhtima, kontrollima, vastama, aitama, arve, töötaja, kandma, täpne.","g_read":"Õpilane leiab loost ja töökuulutustest, mida töötaja peab tegema, mida ta ei pea tegema ja mida ta peab oskama.","g_listen":"Õpilane saab aru kuulamistekstist „Enne vestlust: Markus helistab” (küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab õigesti pean + ma-vorm, ei pea + ma-vorm ning oskan / saan / tahan + da-vorm.","g_use":"Õpilane kirjutab loole 60–80-sõnalise lõpu, kirjutab teksti visiitkaardi järgi ja salvestab pildi kirjelduse."},"tags":{"062_d_markus":"g_listen","062_p_dict":"g_listen"}},
  "a2-064": {"canDo":"Ma saan kuuldust aru tööjuhistest (alusta, too, vii, helista, ära unusta) ja kirjutan sõbrale 50–70-sõnalise kirja oma uuest tööst.","goals":{"g_vocab":"Õpilane kasutab juhise sõnu alustama, lõpetama, tooma, viima, helistama, saatma, kohe, pakk, juhis.","g_read":"Õpilane kirjutab kahe kuulamise järel üles tegevused, ajad ja muudatused ning leiab teadetest vajaliku info.","g_listen":"Õpilane saab aru kuulamistekstidest „Liis annab juhiseid”, „Mis kell mida?”, „Lühikesed teated firmas” ja „Liisi häälsõnum” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane moodustab käskiva vormi (alusta, too, vii, ära unusta; alustage, tooge, ärge unustage).","g_use":"Õpilane teeb häälsõnumist märkmed, lepib kokku plaani ja kirjutab sõbrale 50–70-sõnalise kirja uuest tööst."},"tags":{"064_d_liis":"g_listen","064_d_times":"g_listen","064_p_clips":"g_listen","064_t_voice":"g_listen","064_p_dict":"g_listen"}},
  "a2-065": {"canDo":"Ma näitan kontrollis Harno A2 vormis, et oskan rääkida oma tööst ja kohustustest, saan aru töökuulutusest ja tööjuhisest ning kirjutan lühikese sõnumi (igas osas vähemalt 80%).","goals":{"g_vocab":"Õpilane kasutab mooduli 13 sõnu (amet, töökoht, kontor, kaup, raha, lõuna, teade, oskus) ilma sõnapangata.","g_read":"Õpilane lahendab Harno A2 vormis lugemise (fraasid, kuulutused, sildid, tekst, kiri) ja kuulamise (teated, raadio, juhised, vestlus) vähemalt 80% ulatuses.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiosaade”, „Juhised uuele töötajale” ja „Sõbrad räägivad” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigesti -na vormi, pean + ma-vorm, oskan + da-vorm, kellast kellani ja käskivat vormi.","g_use":"Õpilane kirjutab teksti visiitkaardi järgi ja sõnumi kolleegile, kirjeldab pilti ja peab rollimängus töövestluse."},"tags":{"065_t_l1":"g_listen","065_t_l2":"g_listen","065_t_l3":"g_listen","065_t_l4":"g_listen"}},
  "a2-068": {"canDo":"Ma saan kuuldust aru, mida teine õppida tahab, ja räägin oma õppimise eesmärgist ja plaanist (tahan õppida, proovin lugeda, hakkan kordama).","goals":{"g_vocab":"Õpilane kasutab sõnu eesmärk, proovima, hakkama, unustama, harjutama, sooritama, plaan.","g_read":"Õpilane saab Aune selgitusest, vestlusest ja häälsõnumist aru, mis on teise inimese eesmärk ja mida ta hakkab tegema.","g_listen":"Õpilane saab aru kuulamistekstidest „Aune selgitab tööd”, „Kes mida teeb?” ja „Tomi häälsõnum” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane valib õige infinitiivi: tahan / proovin + da (proovin lugeda), hakkan / pean + ma (hakkan lugema) ja eristab nende tähendust.","g_use":"Õpilane räägib oma õppekaardist ja lepib teisega kokku, kuidas teineteist aidata."},"tags":{"068_d_aune":"g_listen","068_p_talk":"g_listen","068_t_voice":"g_listen"}},
  "a2-070": {"canDo":"Ma näitan kontrollis Harno A2 vormis, et saan aru tunniplaanist ja õpetaja juhistest, palun abi, kui ma ei saa aru, ja kirjutan oma õppeplaanist (igas osas vähemalt 80%).","goals":{"g_read":"Õpilane lahendab Harno A2 vormis lugemise ja kuulamise (väljendid, kuulutused, sildid, tekst, kiri, teated, raadio, vestlus) vähemalt 80% ulatuses.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiovestlus”, „Maret räägib” ja „Sõbrad räägivad” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab kursusel / kursusele, tundi, teie-palvet (korrake, rääkige) ning tahan / proovin + da ja pean / hakkan + ma.","g_use":"Õpilane kirjutab teksti visiitkaardi järgi ja oma õppimisest, kirjeldab pilti ning küsib ja vastab ideekaardi järgi."},"tags":{"070_t_l1":"g_listen","070_t_l2":"g_listen","070_t_l3":"g_listen","070_t_l4":"g_listen"}},
  "a2-072": {"canDo":"Ma räägin viisakalt ja palun abi kodus, tööl ja teeninduses (palun + käsk, Kas sa saad …?, Kas te saate …?, Kas ma võin …?), sõbrale ja võõrale erinevalt.","goals":{"g_vocab":"Õpilane kasutab palve sõnu ja igapäevaseid väljendeid: palve, luba, asemel, Pole tänu väärt, Head reisi!","g_read":"Õpilane leiab sõnumitest, siltidest ja kõnest, kes mida palub ja mida on lubatud teha.","g_notice":"Õpilane moodustab palve: palun + käsk, Kas sa saad / Kas te saate + da-vorm, Kas ma võin / tohin + da-vorm.","g_use":"Õpilane palub viisakalt abi, valib sina või teie ja lepib teisega kokku, keda mida paluda."}},
  "a2-076": {"canDo":"Ma saan kuuldust aru, mida teine eile tegi, ja räägin oma eilsest päevast ja suvest lihtminevikus (olin, tulin, läksin, tegin, sain, nägin; ei olnud).","goals":{"g_vocab":"Õpilane kasutab päeva ja projekti sõnu ärkama, koristama, jõudma, õhtu, puhkus, pilt, lugu, eelmine, kaotama ja helistama.","g_read":"Õpilane saab teadetest, projekti selgitusest ja häälsõnumist aru ning leiab teksti järgi, mida teine tegi ja miks, vähemalt 80% ulatuses.","g_listen":"Õpilane saab aru kuulamistekstidest „Maret räägib projektist”, „Lühikesed teated” ja „Jaani häälsõnum” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane moodustab lihtmineviku vormid olin, tulin, läksin, tegin, sain, nägin, sõin, jõin ja eituse ei olnud, ei tulnud, ei teinud.","g_use":"Õpilane räägib oma eilsest päevast ja suvest, valib teisega loo Lugude õhtule ja salvestab kodus 45–60-sekundilise jutu."},"tags":{"076_d_maret":"g_listen","076_p_clips":"g_listen","076_t_voice":"g_listen"}},
  "a2-077": {"canDo":"Ma saan kuuldust aru, mis teisega juhtus, ja kirjutan 60–80 sõnaga, mis minuga eile juhtus: õiges järjekorras (kõigepealt, siis, pärast seda, äkki, lõpuks).","goals":{"g_vocab":"Õpilane kasutab loo sõnu juhtuma, äkki, õnneks, kahjuks, lõpuks, hilinema, leidma, kukkuma, koosolek ja kiire.","g_read":"Õpilane saab raadiovestlusest, numbritest, häälsõnumist ja lehest aru ning leiab sündmuste aja ja järjekorra vähemalt 80% ulatuses.","g_listen":"Õpilane saab aru kuulamistekstidest „Raadio: Ülle ja Maret”, „Sofia ajad” ja „Büroo häälsõnum” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane märkab järjekorra sõnu kõigepealt, siis, pärast seda, äkki, lõpuks ja tegusõna teist kohta nende järel.","g_use":"Õpilane helistab kadunud asja pärast, kirjeldab pilti, kirjutab 60–80-sõnalise loo sellest, mis eile juhtus, ja parandab seda."},"tags":{"077_d_radio":"g_listen","077_p_numbers":"g_listen","077_t_voice":"g_listen","077_p_dict":"g_listen"}},
  "a2-080": {"canDo":"Ma näitan proovieksamis, et loen kirju ja teateid, saan kuuldust aru, kirjutan sõnumi ja jutustan, mis juhtus (eesmärk on vähemalt 80% igas osas).","goals":{"g_read":"Õpilane lahendab lugemise ja kuulamise ülesanded Harno A2 vormis etteantud ajaga, eesmärk on vähemalt 80%.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiosaade”, „Teade” ja „Vestlus” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab õigesti lihtminevikku, eitust ei + nud, järjekorra sõnu ja kogemuse vormi olen käinud / ei ole käinud.","g_use":"Õpilane kirjutab teksti visiitkaardi järgi ja sõnumi või kirjelduse ning räägib pildist ja küsib kaardi järgi."},"tags":{"080_t_l1":"g_listen","080_t_l2":"g_listen","080_t_l3":"g_listen","080_t_l4":"g_listen","080_d_dict":"g_listen"}},
  "a2-081": {"canDo":"Ma loen teise inimese nädalaplaani ja kirjutan 60–80 sõnaga, mida ma järgmisel nädalal teen ja mida ma kavatsen teha.","goals":{"g_vocab":"Õpilane kasutab sõnu homme, ülehomme, varsti, hiljem, järgmine, plaan, kalender, kavatsema ja tähtis.","g_read":"Õpilane leiab nädalaplaanist ja teadetest, kes mida ja millal teeb, ning saab kõnest ja häälsõnumist aru vähemalt 80% ulatuses.","g_listen":"Õpilane saab aru kuulamistekstidest „Anna helistab Sofiale”, „Keelekooli automaatvastaja” ja „Lucía häälsõnum” (lüngad).","g_notice":"Õpilane ütleb tulevikku oleviku ja ajasõnaga (homme lähen, neljapäeval tuleb), kasutab kavatsen + da-vormi ja hoiab tegusõna teisel kohal.","g_use":"Õpilane jutustab Sofia nädalast, kirjeldab pilti, leiab teisega vaba aja, kirjutab 60–80 sõna oma nädalast ja salvestab kodus 45–60-sekundilise jutu."},"tags":{"081_d_anna":"g_listen","081_p_numbers":"g_listen","081_t_voice":"g_listen"}},
  "a2-085": {"canDo":"Ma näitan kontrollis Harno A2 vormis, et räägin oma plaanidest, lepin kokku täpse aja ja koha, kasutan lauset „kui …, siis …” ja kirjutan kohtumise muutmise sõnumi (igas osas vähemalt 80%).","goals":{"g_read":"Õpilane saab Harno A2 vormis lugemis- ja kuulamisülesannetes aru plaanidest, teadetest ja kokkulepetest.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiovestlus”, „Sofia häälsõnum” ja „Sõbrad räägivad” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab tulevikku ajasõnaga, kui + olevik, siis …, sobima-lauset ja kokkuleppe fraase õigesti.","g_use":"Õpilane kirjutab visiitkaardi teksti ja kohtumise muutmise sõnumi, kirjeldab pilti ning küsib ja vastab kaardi järgi."},"tags":{"085_t_l1":"g_listen","085_t_l2":"g_listen","085_t_l3":"g_listen","085_t_l4":"g_listen"}},
  "a2-061": {"canDo":"Ma loen, kes kus ja kellena töötab, ja räägin 6–8 lausega oma või väljamõeldud tööst: amet, töökoht, tööaeg ja ülesanded.","goals":{"g_vocab":"Õpilane nimetab ameteid ja töökohti ning kasutab sõnu kolleeg, klient, ülesanne, tööpäev, palk, juhataja.","g_read":"Õpilane leiab sõnumitest, raadiost ja siltidelt, kes kus ja kellena töötab, mida ta peab tegema ja mille eest ta vastutab.","g_listen":"Õpilane saab aru kuulamistekstidest „Raadio: töömess laupäeval” ja „Ene teade keelekoolis” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane eristab vorme ta on õpetaja / töötab õpetajana, töötab poes (mitte poesse), vastutab kauba eest, teenindab kliente.","g_use":"Õpilane räägib 6–8 lausega oma või väljamõeldud tööst ja küsib tööandjalt kaks küsimust."},"tags":{"061_d_radio":"g_listen","061_p_ene":"g_listen"}},
  "a2-063": {"canDo":"Ma saan kuuldust aru tööpakkumisest, leian kuulutusest tööaja, palga ja nõuded ning lepin teisega kokku, mis töö sobib ja miks.","goals":{"g_vocab":"Õpilane kasutab töökuulutuse sõnu vahetus, kogemus, vajalik, kuulutus, leping, sobima, pakkuma, valima.","g_read":"Õpilane saab häälsõnumist ja vestlusest aru ning leiab kuulutusest ja töögraafikust tööaja, palga, nõuded ja kandideerimise viisi.","g_listen":"Õpilane saab aru kuulamistekstidest „Liis ja Eha jätavad sõnumi” ja „Anna ja Sofia räägivad” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane moodustab kella kaheksast viieni, esmaspäevast reedeni, loeb lühendeid E–R, 8–17 ja kasutab kumb, hommikune / õhtune vahetus.","g_use":"Õpilane võrdleb kaht tööd, lepib partneriga kokku, mis sobib ja miks, ning helistab keelekooli oma tundide pärast."},"tags":{"063_d_calls":"g_listen","063_p_talk":"g_listen"}},
  "a2-066": {"canDo":"Ma loen kursuse infot ja räägin oma eesti keele kursusest vähemalt kuue lausega: kus ja millal on tunnid, mida me teeme ja miks ma õpin.","goals":{"g_vocab":"Õpilane kasutab kursuse sõnu (kursus, tund, õpetaja, ülesanne, kodutöö, test, oskus, tunniplaan, õpik, eksam) oma õppimisest rääkides.","g_read":"Õpilane leiab kursuse tekstist ja suvekursuste infost tundide aja, koha, kestuse ja hinna.","g_notice":"Õpilane eristab vorme kursusel / kursusele / kursuselt, tunnis / tundi / tunnist ja kasutab esmaspäeviti, õhtuti, kaks korda nädalas.","g_use":"Õpilane räägib oma kursusest vähemalt kuue lausega, küsib telefonis kursuse kohta ja kirjutab kolleegile 30–50-sõnalise sõnumi."}},
  "a2-067": {"canDo":"Ma loen õpetaja juhiseid ja kirjutan õpetajale 50–70-sõnalise kirja: millest ma aru ei saanud ja mis abi ma palun.","goals":{"g_vocab":"Õpilane kasutab abi palumise sõnu: aru saama, kordama, tähendama, näide, aeglaselt, küsimus, sõna, lause.","g_read":"Õpilane leiab õpetaja lehest, kirjast ja kõnest, millest inimene aru ei saanud, mida ta peab tegema ja mis on tähtaeg.","g_listen":"Õpilane saab aru kuulamistekstidest „Lucía helistab Maretile” ja „Mida õpetaja ütles?” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane moodustab käsu sina- ja teie-vormis (korda – korrake, räägi – rääkige) ja viisaka küsimuse „Kas te saate + da-vorm?”.","g_use":"Õpilane palub tunnis abi vähemalt nelja lausega ja kirjutab õpetajale 50–70-sõnalise kirja."},"tags":{"067_d_call":"g_listen","067_p_clips":"g_listen"}},
  "a2-069": {"canDo":"Ma saan kuuldust aru, kuidas teine õpib, ja kirjutan oma kahe nädala õppeplaani 60–80 sõnaga ja vähemalt viie ajasõnaga (iga päev, kaks korda nädalas …).","goals":{"g_vocab":"Õpilane kasutab plaani sõnu (kontrollima, kalender, minut, uudis) ja sagedusväljendeid iga päev, igal õhtul, kaks korda nädalas.","g_read":"Õpilane saab raadiost ja häälsõnumist aru, kuidas teine õpib ja mis peab plaanis olema, ning leiab plaanist tegevused ja nende sageduse.","g_listen":"Õpilane saab aru kuulamistekstidest „Raadio: Maret ja Ülle”, „Ene loeb numbreid” ja „Mareti häälsõnum” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane paneb ajasõna lause algusesse (Igal õhtul kordan ma sõnu) ja valib õige infinitiivi: tahan + da, pean / hakkan + ma.","g_use":"Õpilane kirjutab 60–80-sõnalise kahe nädala plaani vähemalt viie ajasõnaga ja lepib õpisõbraga kokku, millal nad koos õpivad."},"tags":{"069_d_radio":"g_listen","069_p_numbers":"g_listen","069_t_voice":"g_listen","069_p_dict":"g_listen"}},
  "a2-071": {"canDo":"Ma võtan külalise vastu või lähen ise külla ja räägin 2–3 minutit viisakalt: tervitan, pakun või tänan ja lahkun.","goals":{"g_vocab":"Õpilane kasutab külaskäigu sõnu ja väljendeid: külla, külas, kutse, kingitus, võõrustaja, Aitäh kutse eest!, Mul on aeg minna.","g_read":"Õpilane saab kutsest ja raadiovestlusest aru: kes kutsub, millal, kuhu ja kuidas külas ollakse.","g_listen":"Õpilane saab aru kuulamistekstidest „Sandra kutse ja Tomi mure” ja „Kuidas külla minna?” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab teie-käsku (tulge, võtke) ja osastavat pakkumises (Kas soovite teed?), eristab külla ja külas.","g_use":"Õpilane räägib külas 2–3 minutit viisakalt: tervitab, pakub või keeldub, tänab ja lahkub."},"tags":{"071_d_voice":"g_listen","071_p_radio":"g_listen"}},
  "a2-073": {"canDo":"Ma saan kuuldust aru, kes tuleb ja kes ei tule, ja kirjutan 50–70-sõnalise vastuse: nõustun või keeldun viisakalt, ütlen põhjuse sõnaga „sest” ja pakun teist aega.","goals":{"g_vocab":"Õpilane kasutab väljendeid muidugi, hea meelega, kahjuks, sobib, äkki, ma annan teada.","g_read":"Õpilane saab häälsõnumitest ja telefonikõnest aru, kes tuleb, kes ei tule ja miks.","g_listen":"Õpilane saab aru kuulamistekstidest „Seitse häälsõnumit”, „Sofia helistab tagasi” ja „Rongid ja ajad” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab eitust (ma ei saa, see ei sobi), ei saa + da-vorm, pean + ma-vorm ja sest + lause.","g_use":"Õpilane kirjutab kutsele viisaka vastuse: nõustub või keeldub, ütleb põhjuse ja pakub teist aega."},"tags":{"073_d_msgs":"g_listen","073_d_call":"g_listen","073_p_times":"g_listen","073_p_dict":"g_listen"}},
  "a2-074": {"canDo":"Ma loen lugu sõnumites ja kirjutan sõbrale või tuttavale 50–70-sõnalise sõnumi (kutse, tänu või aja muutmine), kus on eesmärk, vajalik info ja sobiv lõpp.","goals":{"g_vocab":"Õpilane kasutab sõnumi sõnu ja lõppe: sõnum, rahakott, leidma, kaotama, Kallistan!, Tervitades.","g_read":"Õpilane loeb lugu sõnumites ja saab aru, mis juhtus, kes aitas ja mis järjekorras sõnumid olid.","g_listen":"Õpilane saab aru kuulamistekstist „Hommik Viktori talus” (küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab õigesti Aitäh … eest!, Palun anna teada, oma ja sihitise vormi (leidsin rahakoti) ning parandab oma teksti.","g_use":"Õpilane kirjutab tänu, kutse või aja muutmise sõnumi: pöördumine, eesmärk, info, palve ja lõpp."},"tags":{"074_d_voice":"g_listen","074_p_dict":"g_listen"}},
  "a2-075": {"canDo":"Ma näitan kontrollis Harno A2 vormis, et oskan külas viisakalt rääkida, palun abi, nõustun või keeldun ja kirjutan lühikese sõnumi (igas osas vähemalt 80%).","goals":{"g_vocab":"Õpilane kasutab mooduli sõnu ja väljendeid ilma abita.","g_read":"Õpilane saab Harno A2 vormis lugemis- ja kuulamisülesannetes aru kutsetest, sõnumitest ja teadetest.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiovestlus”, „Markuse häälsõnum” ja „Sõbrad räägivad” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab teie-käsku, da-vormi pärast sõnu saan ja võin ning Aitäh … eest!","g_use":"Õpilane kirjutab sõnumi, kirjeldab pilti, küsib ja vastab ning keeldub viisakalt."},"tags":{"075_t_l1":"g_listen","075_t_l2":"g_listen","075_t_l3":"g_listen","075_t_l4":"g_listen"}},
  "a2-078": {"canDo":"Ma loen lühikest lugu minevikus, vastan küsimustele kes, kus, millal ja miks ning räägin oma loo algusest lõpuni vähemalt kaheksa lausega.","goals":{"g_vocab":"Õpilane kasutab loo sõnu mälestus, raamat, kiri, unustama, naerma, tagasi, pood, vana, jaam ja aasta.","g_read":"Õpilane vastab loo ja kava küsimustele kes, kus, millal, mis juhtus ja miks vähemalt 80% ulatuses.","g_notice":"Õpilane kasutab ajaväljendeid ühel hommikul, järgmisel päeval, kaks aastat tagasi ja lihtmineviku vorme ma, ta ja nad vormis.","g_use":"Õpilane räägib oma loo vähemalt kaheksa lausega, küsib teise loo kohta märksõnade järgi ja kirjutab sõbrale sõnumi."}},
  "a2-079": {"canDo":"Ma loen teiste kogemustest ja kirjutan 50–70-sõnalise kirja: kus ma olen käinud, mida ma olen proovinud ja mida ma ei ole veel teinud.","goals":{"g_vocab":"Õpilane kasutab sõnu kunagi, juba, veel, kogemus, proovima, käima, ujuma, lendama, kord ja reis.","g_read":"Õpilane leiab vastustest ja kuulutustest, kes mida on proovinud, ning saab mängust ja vestlusest aru vähemalt 80% ulatuses.","g_listen":"Õpilane saab aru kuulamistekstidest „Mäng kohvikus” ja „Kes on mida proovinud?” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab vormi olen käinud / ei ole käinud kogemuse kohta ja lihtminevikku kindla aja kohta.","g_use":"Õpilane seletab teisele kirja sisu, kirjutab 50–70-sõnalise kirja oma kogemustest ja salvestab kodus 45–60-sekundilise jutu."},"tags":{"079_d_game":"g_listen","079_p_match":"g_listen"}},
  "a2-082": {"canDo":"Ma saan kuuldust aru, kes, millal ja kus kokku saab, ja kirjutan 40–70-sõnalise sõnumi, millega kinnitan või muudan kokkulepet.","goals":{"g_vocab":"Õpilane kasutab sõnu kokkulepe, kohtuma, kohtumine, sobima, vaba, kinnitama, muutma, täpne, aadress ja kaasa.","g_read":"Õpilane saab häälsõnumist ja raadiost aru, kes, millal ja kus kokku saab, ning leiab rongiajast vajaliku info.","g_listen":"Õpilane saab aru kuulamistekstidest „Ema häälsõnum”, „Raadio: kuidas kokku leppida?” ja „Ene räägib retkest” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab kokkuleppe samme (Kas … sobib?, Kahjuks ei saa, Aga kas …?, Äkki …?) ja vorme mulle sobib, mul on aega.","g_use":"Õpilane küsib ja pakub aega, seletab kuuldud sõnumit teisele, kirjutab 40–70-sõnalise kinnitava sõnumi ja salvestab kodus 45–60-sekundilise jutu."},"tags":{"082_d_helgi":"g_listen","082_d_radio":"g_listen","082_p_ene":"g_listen"}},
  "a2-083": {"canDo":"Ma loen retke kava, ütlen kuus lauset mustriga „kui + olevik, siis …” (ilm, aeg, raha) ja lepin teisega kokku, mida me teeme.","goals":{"g_vocab":"Õpilane kasutab sõnu ilm, vihm, päike, tuul, külm, soe, retk, kava, otsus ja raha.","g_read":"Õpilane leiab kavast ja kirjast, mis saab eri ilmaga, ning saab ilmateatest aru vähemalt 80% ulatuses.","g_listen":"Õpilane saab aru kuulamistekstist „Ilmateade raadios” (lüngad ja etteütlus).","g_notice":"Õpilane moodustab lause „kui + olevik, siis …” ja paneb pärast sõna siis kohe tegusõna.","g_use":"Õpilane lepib teisega kokku plaani A ja plaani B, järjestab tegevused, kirjutab otsuse ja salvestab kodus 45–60-sekundilise jutu."},"tags":{"083_p_forecast":"g_listen","083_p_dict":"g_listen"}},
  "a2-084": {"canDo":"Ma saan kuuldust aru, mis plaanis muutus, ja lepin telefonis kokku uue aja ja koha: ütlen, mis ei sobi, pakun uut aega ja kinnitan kokkuleppe.","goals":{"g_vocab":"Õpilane kasutab sõnu muutus, katki, asemel, ära jääma, vahetama, pakkuma, helistama, firma, lahendus ja probleem.","g_read":"Õpilane saab telefonisõnumitest ja vestlusest aru, mis muutus ja kes mida teeb, ning leiab kirjadest uue aja.","g_listen":"Õpilane saab aru kuulamistekstidest „Kaheksa sõnumit Enele” ja „Kes mida teeb?” (küsimused kuuldu kohta).","g_notice":"Õpilane kasutab väljendeid kella üheksa asemel, jääb ära, Mis ajaks?, Selge, siis … ja vorme sulle, talle, meid.","g_use":"Õpilane teeb telefonikõne kaks korda ja lepib lõpuks kokku uue aja ja koha, kirjutab kirja kohtumise muutmisest ja salvestab kodus 45–60-sekundilise jutu."},"tags":{"084_d_clips":"g_listen","084_p_match":"g_listen"}},
  "a2-086": {"canDo":"Ma loen trepikoja, poe või kooli lühikest teadet, leian sealt olulised faktid (mis, kus, millal, kellele, mida teha) ja kirjutan 40–60 sõnaga oma kuulutuse.","goals":{"g_vocab":"Õpilane kasutab teadete ja kuulutuste sõnu: teade, kuulutus, elanik, tasuta, lisainfo, müüa, leitud.","g_read":"Õpilane leiab lühikestest teadetest ja siltidest vastused küsimustele mis, kus, millal, kellele ja mida teha.","g_notice":"Õpilane kasutab teate palvevorme: palume + da-vorm, palume mitte + da-vorm, helistage, tooge.","g_use":"Õpilane kirjutab 40–60-sõnalise kuulutuse ja räägib kuulutuse pärast telefonis."}},
  "a2-087": {"canDo":"Ma loen tabloolt ja teadetest, mis muutus, räägin sellest sõbrale ja lepin kokku, mida edasi teha.","goals":{"g_vocab":"Õpilane kasutab teadaande sõnu: tähelepanu, hilineb, väljub, saabub, perroon, jääb ära, vabandame.","g_read":"Õpilane leiab tabloolt ja lühikestest tekstidest aja, numbri, perrooni või värava ja selle, mis muutus.","g_listen":"Õpilane saab aru kuulamistekstist „Jaamas kostab veel teateid” (küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab ta-vormi (hilineb, väljub, saabub) ja järgarvu kohavorme (kolmandalt perroonilt, kolmandale perroonile, järgmises peatuses).","g_use":"Õpilane räägib, mis muutus, küsib infolauast ja lepib paarilisega kokku, mida edasi teha."},"tags":{"087_d_clips":"g_listen","087_p_dict":"g_listen"}},
  "a2-088": {"canDo":"Ma saan kuuldud juhisest aru ja kirjutan 60–80 sõnaga oma juhise: sammud on õiges järjekorras (esmalt, seejärel, lõpuks) ja teie-vormis.","goals":{"g_vocab":"Õpilane kasutab juhise sõnu: esmalt, seejärel, lõpuks, vajutama, sisestama, valima, ekraan, nupp, kood.","g_read":"Õpilane saab kuuldud ja loetud juhisest aru ning leiab sammud ja faktid.","g_listen":"Õpilane saab aru kuulamistekstidest „Markus seletab telefonis” ja „Raadio: pakk automaadis” (küsimused kuuldu kohta).","g_notice":"Õpilane moodustab teie-käsu da-vormist (valida → valige, võtta → võtke) ja keelu ärge + vorm.","g_use":"Õpilane seletab juhist telefonis ja kirjutab 60–80-sõnalise juhise: plaan, tekst, parandamine."},"tags":{"088_d_call":"g_listen","088_d_radio":"g_listen"}},
  "a2-089": {"canDo":"Ma saan kuuldust aru ja panen telefonikõnest kirja nime, numbri, kellaaja, kuupäeva ja koha ning tutvustan seda infot uuele õppijale.","goals":{"g_vocab":"Õpilane kasutab kõne sõnu ja numbreid: kuupäev, kellaaeg, korrus, aadress, perekonnanimi, tähthaaval, kordama.","g_read":"Õpilane kirjutab kuuldud kõnest ja sõnumitest üles nime, telefoninumbri, kellaaja, kuupäeva ja koha.","g_listen":"Õpilane saab aru kuulamistekstidest „Natalja helistab koolile”, „Raadio: Ene telefonis” ja „Kolm häälsõnumit” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab järgarvu ja kuupäeva -l-vormi ja küsib üle: Kas te saate korrata? Kas ma sain õigesti aru?","g_use":"Õpilane lepib paarilisega kokku, mis tuleb infokaardile, ja tutvustab kaarti uuele õppijale."},"tags":{"089_d_call":"g_listen","089_d_radio":"g_listen","089_t_msgs":"g_listen","089_p_dict":"g_listen"}},
  "a2-090": {"canDo":"Ma näitan kontrollis Harno A2 vormis, et saan teadetest, juhistest ja kuuldud infost aru ja kirjutan lühikese teate (igas osas vähemalt 80%).","goals":{"g_vocab":"Õpilane kasutab mooduli 18 sõnavara (teade, kuulutus, teadaanne, juhis, kuupäev) ilma sõnapangata.","g_read":"Õpilane lahendab Harno A2 vormis lugemise (5 osa) ja kuulamise (4 osa), iga salvestus kaks korda.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiovestlus”, „Dmitri häälsõnum” ja „Sõbrad räägivad” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab palvevorme, teie-käsku, järgarvude kohavorme ja kuupäeva -l-vormi.","g_use":"Õpilane kirjutab visiitkaardi teksti ja teate ning räägib pildist ja annab telefonis infot."},"tags":{"090_t_l1":"g_listen","090_t_l2":"g_listen","090_t_l3":"g_listen","090_t_l4":"g_listen","090_d_tf":"g_listen"}},
  "a2-091": {"canDo":"Ma kuulan häälsõnumit ja kirjutan selle põhjal 40–70-sõnalise kutse või sõnumi: kes, mida, millal, kus ja miks.","goals":{"g_vocab":"Õpilane kasutab sõnumi ja kutse sõnu kutse, külaline, vastama, tasuta, kahjuks, kohtumiseni ja kuuleb numbreid, kellaaegu ja hindu.","g_read":"Õpilane leiab häälsõnumist, raadiosaatest ja kolmest sõnumist, kes, mida, millal, kus ja mis ajaks.","g_listen":"Õpilane saab aru kuulamistekstidest „Ene jättis sõnumi”, „Raadio ja sõnumid” ja „Kolm viimast sõnumit” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab vorme reedel / reedeks, Kas sa saad + da-vorm, ei saa, sest ja sõnumi nelja osa.","g_use":"Õpilane seletab õhtut teisele, jätab häälsõnumi ja kirjutab 40–70-sõnalise kutse."},"tags":{"091_d_ene":"g_listen","091_p_radio":"g_listen","091_t_answers":"g_listen"}},
  "a2-092": {"canDo":"Ma saan kuuldust aru, mis muutus, ja helistan teenindusse: küsin, täpsustan, pakun teist lahendust ja lõpetan viisakalt.","goals":{"g_vocab":"Õpilane kasutab teeninduse väljendeid: Kas teil on …?, Mul on vaja …, Kui kaua see võtab?, … on otsas, Siis võtan hoopis …, Aitäh abi eest!","g_read":"Õpilane leiab kõnest, hinnakirjast ja firmade kirjeldustest, mis muutus, hinna, aja ja koha.","g_listen":"Õpilane saab aru kuulamistekstidest „Jaan helistab” ja „Sofia helistab pagariärisse” (lüngad).","g_notice":"Õpilane kasutab vorme Kas teil on kooki? / Siis võtan koogi ja parandab tellimuse vead.","g_use":"Õpilane helistab enne reegleid ja pärast neid, küsib ja vastab kaardi järgi, lepib kokku ja lahendab telefonis probleemi."},"tags":{"092_d_jaan":"g_listen","092_p_piret":"g_listen"}},
  "a2-093": {"canDo":"Ma loen lugu ja kirjutan plaani järgi 60–80-sõnalise jutu või kirjelduse, kus on vähemalt kuus seos- või ajasõna.","goals":{"g_vocab":"Õpilane kasutab loo sõnu närvis, üllatunud, võõras, kõigepealt, pärast seda, lõpuks, seepärast, tavaliselt.","g_read":"Õpilane leiab loost ja sõnumist, mis juhtus, miks ja mis järjekorras, ning loeb teksti kiiresti.","g_listen":"Õpilane saab aru kuulamistekstidest „Natalja kuuleb koolis” ja „Olga ja Irina telefonis” (küsimused kuuldu kohta).","g_notice":"Õpilane seob laused sõnadega sest, seepärast, aga, kõigepealt, lõpuks ja kasutab lihtminevikku.","g_use":"Õpilane jutustab loo, teeb plaani ja kirjutab 60–80-sõnalise jutu ning parandab seda."},"tags":{"093_d_voice":"g_listen","093_p_call":"g_listen"}},
  "a2-094": {"canDo":"Ma loen näidist ja räägin tuttaval teemal 1,5–2 minutit märksõnade järgi, ilma paberilt lugemata, ning vastan kolmele lisaküsimusele.","goals":{"g_vocab":"Õpilane kasutab kõne väljendeid: Täna räägin ma …, kõigepealt, teiseks, näiteks, kokkuvõtteks, Aitäh kuulamast!, ja igapäevaseid viisakaid lauseid.","g_read":"Õpilane leiab loetud ja kuuldud kõnest osad, teema, näite ja kokkuvõtte.","g_listen":"Õpilane saab aru kuulamistekstist „Tomi kõne” (küsimused kuuldu kohta).","g_notice":"Õpilane ütleb teema seestütlevas: tööst, perest, vabast ajast, ja kasutab kõne plaani.","g_use":"Õpilane räägib enne reegleid ja pärast neid, teeb märksõnad, vastab lisaküsimustele ja räägib 1,5–2 minutit."},"tags":{"094_p_tom":"g_listen","094_d_topics":"g_listen"}},
  "a2-095": {"canDo":"Ma näitan kontrollis Harno A2 vormis, et kirjutan sõnumi ja kirjelduse, saan aru kuuldust ja loetust, räägin teemal 1,5–2 minutit ja lahendan dialoogis olukorra (igas osas vähemalt 80%).","goals":{"g_read":"Õpilane lahendab Harno A2 vormis lugemise ja kuulamise (viisakad laused, teated, sildid, tekst, kiri, raadiovestlus, vestlus).","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiovestlus”, „Maret räägib” ja „Sõbrad räägivad” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab mooduli vorme ilma toeta: reedeks, kooki / koogi, tööst, seos- ja ajasõnad.","g_use":"Õpilane kirjutab visiitkaardi teksti ja kirjelduse, kirjeldab pilti, vastab küsimustele ja lahendab dialoogis olukorra."},"tags":{"095_t_l1":"g_listen","095_t_l2":"g_listen","095_t_l3":"g_listen","095_t_l4":"g_listen"}},
  "a2-096": {"canDo":"Ma saan kuuldud eksamisaatest aru, räägin, mis on mulle raske, ja lepin paarilisega kokku, kuidas me eksamiks harjutame.","goals":{"g_vocab":"Õpilane kasutab eksami sõnu ja väljendeid: osa, punkt, ülesanne, paariline, ideekaart, Palun korrake!, Üks hetk, palun.","g_read":"Õpilane saab raadiosaatest ja õppijate juttudest aru, kuidas eksam käib ja mis kellelegi raske on (õige / vale, valikvastused, lühivastused).","g_listen":"Õpilane saab aru kuulamistekstidest „Mida nad kardavad?”, „Ene helistab Tomile” ja „Raadio” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigesti pean + ma-vormi, tahan + da-vormi ja võrdlust raskem kui, kergem kui.","g_use":"Õpilane räägib paarilisega oma nõrgast osast, palub vajaduse korral korrata ja lepib kokku kaks asja, mida nad koos harjutavad."},"tags":{"096_d_voices":"g_listen","096_p_ene":"g_listen","096_p_radio":"g_listen"}},
  "a2-097": {"canDo":"Ma teen eksami neli osa etteantud aja jooksul ja saan teada, mis osa on minu jaoks kõige nõrgem (eesmärk on vähemalt 80% igas osas).","goals":{"g_vocab":"Õpilane mõistab eksami juhiseid ja igapäevateemade sõnu ilma sõnaraamatuta.","g_read":"Õpilane lahendab Harno A2 vormis lugemise ja kuulamise ülesanded etteantud aja jooksul.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiosaade”, „Teade” ja „Vestlus” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigeid vorme kirjas, sõnumis ja kirjelduses: kus / kuhu / kust, ma- ja da-vorm, minevik.","g_use":"Õpilane kirjutab visiitkaardi järgi vähemalt 25 sõna ja sõnumi või kirjelduse vähemalt 30 sõnaga ning räägib pildist ja ideekaardi järgi."},"tags":{"097_t_l1":"g_listen","097_t_l2":"g_listen","097_t_l3":"g_listen","097_t_l4":"g_listen"}},
  "a2-098": {"canDo":"Ma loen näidisteksti, leian oma korduvad vead ja kirjutan plaani järgi 60–80 sõnaga kirjelduse, mille ma ise üle kontrollin.","goals":{"g_vocab":"Õpilane seob lauseid: sest, aga, seepärast, kõigepealt, pärast seda, lõpuks.","g_read":"Õpilane loeb tagasisidekirja, näidisteksti ja lehelugu, leiab teksti plaani ja saab kuuldud sõnumist aru, mida teha.","g_notice":"Õpilane parandab kolm korduvat viga: pean + ma / tahan + da, eitus minevikus (ei läinud), kuhu / kus / kust.","g_use":"Õpilane teeb plaani, kirjutab 60–80-sõnalise kirjelduse, kontrollib seda rubriigi järgi ja kirjutab puhtalt ümber."}},
  "a2-099": {"canDo":"Ma teen proovieksami kõik neli osa õigel ajal, võrdlen punkte Kontroll 20 tulemusega ja nimetan oma järgmise sammu (eesmärk on vähemalt 80% igas osas).","goals":{"g_read":"Õpilane lahendab lugemise ja kuulamise ülesanded Harno A2 vormis õigel ajal ja kontrollib vastused üle.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiosaade”, „Teade” ja „Vestlus” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane võrdleb tulemusi: parem, rohkem, vähem, kergem kui, ning kasutab eksami tekstides õigeid vorme.","g_vocab":"Õpilane mõistab uute teemade sõnu kontekstis ilma sõnaraamatuta.","g_use":"Õpilane kirjutab ja räägib eksami vormis ning ütleb, mis on tema järgmine samm."},"tags":{"099_t_l1":"g_listen","099_t_l2":"g_listen","099_t_l3":"g_listen","099_t_l4":"g_listen"}},
  "a2-100": {"canDo":"Ma lahendan lõpphindamise neli osa iseseisvalt, hindan oma oskusi „Ma oskan…” lausetega ja koostan oma plaani B1 poole (eesmärk on vähemalt 80% igas osas).","goals":{"g_vocab":"Õpilane kasutab A2 kursuse põhisõnavara (kodu, töö, tervis, linn, vaba aeg) ilma sõnaraamatuta.","g_read":"Õpilane lahendab Harno A2 vormis lugemise ja kuulamise ülesanded iseseisvalt ja õigel ajal.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiosaade”, „Teade” ja „Vestlus” (lüngad, küsimused kuuldu kohta ja etteütlus).","g_notice":"Õpilane kasutab vorme ilma abita: kus / kuhu / kust, ma- ja da-vorm, minevik, võrdlus.","g_use":"Õpilane kirjutab ja räägib eksami vormis ning koostab oma plaani B1 poole."},"tags":{"100_t_l1":"g_listen","100_t_l2":"g_listen","100_t_l3":"g_listen","100_t_l4":"g_listen","100_d_dict":"g_listen"}},
  // supplement „Lihtminevik: si- ja i-minevik” (a2/lihtminevik.js)
  "a2-l01": {"canDo": "Ma tunnen ära i-mineviku tegusõnad (tulin, sain, sõin, jõin) ja kirjutan kõigis isikutes, mida ma eile tegin.", "goals": {"g_read": "Õpilane leiab Rasmuse postitusest, Kertu häälsõnumist ja treeneri sõnumist, mida keegi tegi ja millal.", "g_listen": "Õpilane saab aru kuulamistekstidest „Kertu häälsõnum” ja „Treeneri sõnum” (lüngad).", "g_notice": "Õpilane eristab si- ja i-minevikku (mängisin – tulin, käisin – sain), teab i-rühma sõnu ja pöörab neid kõigis isikutes.", "g_use": "Õpilane räägib ja kirjutab oma eilsest päevast vähemalt viie i-mineviku vormiga."}, "tags": {"l01_d_voice": "g_listen", "l01_p_coach": "g_listen"}},
  "a2-l02": {"canDo": "Ma ütlen ja kirjutan, mida ma ei teinud (ei olnud, ei tulnud, ei läinud, ei söönud), ja vabandan, miks ma kuhugi ei jõudnud.", "goals": {"g_read": "Õpilane saab aru klassijuhataja vestlusest, Joonase vabandusest, Hanna telefonikõnest ja treeneri sõnumist: mida keegi tegi ja mida ei teinud.", "g_listen": "Õpilane saab aru kuulamistekstidest „Klassijuhataja küsib”, „Hanna kõne” ja „Treeneri häälsõnum” (lüngad).", "g_notice": "Õpilane moodustab eituse ei + -nud kõigis isikutes, ka i-mineviku sõnadel (ei läinud, ei söönud, ei joonud, ei teinud, ei näinud).", "g_use": "Õpilane vabandab ja selgitab suuliselt ja kirjalikult, miks ta ei tulnud, vähemalt viie eitusega."}, "tags": {"l02_d_class": "g_listen", "l02_p_call": "g_listen", "l02_t_coach": "g_listen"}},
  "a2-l03": {"canDo": "Ma kasutan jaatavat ja eitavat lihtminevikku kõigis isikutes ja saan aru lühikesest kuuldud loost.", "goals": {"g_read": "Õpilane saab aru Laura lühikesest jutust uuest klassivennast.", "g_notice": "Õpilane valib ja kirjutab jaatava ja eitava minevikuvormi (sõime, ei rääkinud, läksid, ei joonud).", "g_use": "Õpilane kirjutab 4–6 lauset oma eilsest koolipäevast jaatuse ja eitusega."}},
  "a2-l04": {"canDo": "Ma parandan oma minevikuvormide vead ja kirjutan sõbrale, mida ma tegin ja mida ei teinud.", "goals": {"g_read": "Õpilane mõistab Rasmuse lugu kadunud telefonist ja valib sobiva vormi.", "g_notice": "Õpilane parandab tüüpvead (tulesin, ei läksin, ei sõinud) ja kasutab õiget i-mineviku ja eituse vormi.", "g_use": "Õpilane kirjutab sõbrale oma nädalavahetusest, mis õnnestus ja mis ei õnnestunud."}},
  // supplement „Kus? Kuhu? Kust? (kontroll)” (a2/kohakaanded.js): the three goals are the check's three sub-skills
  "a2-k01": {"canDo": "Ma valin õige küsisõna (kus? kuhu? kust?) ja kirjutan kohasõna õige lõpuga: kodus, koju, kodust, kooli, poest, tööl.", "goals": {"g_kus": "Küsisõna: õpilane valib õige küsisõna kus?, kuhu? või kust? (8 lauset).", "g_koht": "Sees või peal: õpilane valib sisekohakäände (-s, -sse, -st) või väliskohakäände (-l, -le, -lt) (8 lauset).", "g_lopp": "Õige lõpp: õpilane kirjutab kohasõna õige lõpuga: koju, kodust, kooli, poodi, tuppa, töölt, tööl (8 lauset)."}},
  "a2-k02": {"canDo": "Ma valin õige küsisõna (kus? kuhu? kust?) ja kirjutan kohasõna õige lõpuga: kodus, koju, kodust, parki, köögis, tööl.", "goals": {"g_kus": "Küsisõna: õpilane valib õige küsisõna kus?, kuhu? või kust? (8 lauset).", "g_koht": "Sees või peal: õpilane valib sisekohakäände (-s, -sse, -st) või väliskohakäände (-l, -le, -lt) (8 lauset).", "g_lopp": "Õige lõpp: õpilane kirjutab kohasõna õige lõpuga: koju, kodust, kooli, poodi, tuppa, töölt, tööl (8 lauset)."}},
};
